rooms = {}
audio_cache = {}  # key -> (mp3 bytes, timestamp)


def new_room_code() -> str:
    while True:
        code = "".join(random.choices(string.ascii_uppercase + string.digits, k=4))
        if code not in rooms:
            return code


def connected(room):
    return [p for p in room["players"] if p["ws"] is not None]


TEAM_NAMES = ["Rojo", "Azul", "Verde", "Amarillo"]


def host_player(room):
    return next((p for p in room["players"] if not p.get("gone") and not p.get("spectator")), None)


def score_owner(room, player):
    return f"equipo:{player['team']}" if room.get("team_count") and player.get("team") is not None else player["id"]


def sync_score(room, player, score):
    for member in room["players"]:
        if member is player or (room.get("team_count") and member.get("team") == player.get("team") and not member.get("spectator")):
            room["scores"][member["id"]] = score


def current_player(room):
    active = [p for p in room["players"]
              if not p.get("gone") and not p.get("out") and not p.get("spectator")]
    if not active:
        return None
    # These games own their turn separately from the quiz turn counter.
    game = room.get("game")
    st = room.get(game) if game else None
    routed = False
    pid = None
    if st and room.get("phase") not in ("lobby", "gameover"):
        if game in ("cartas", "carrera", "flota") and st.get("order"):
            pid = st["order"][st["idx"]]
            routed = True
        elif game == "truco" and st.get("hand"):
            hand = st["hand"]
            pending = (hand.get("stake_pending") if room["phase"] == "truco_canto"
                       else hand.get("envido_pending") if room["phase"] == "truco_envido"
                       else None)
            pid = next((q for q in st["order"] if q != pending[1]), None) if pending else hand["to_play"]
            routed = True
        elif game in ("corazones", "trenes") and st.get("hand"):
            pid = st["hand"]["to_play"]
            routed = True
        elif game == "bingo":
            pid = bingo_host(room)
            routed = True
        elif game in ("poker", "chinchon", "escoba", "uno_oro", "bingo", "escalera", "rosco", "pistas", "oca", "aim", "sapo", "bolos", "hockey", "tejo", "pingpong", "tenis", "ajedrez", "torre", "caballos", "autitos", "aviones", "viborita", "comepuntos", "fantasmas", "castillo", "zombi", "grua", "tesoros","laberinto","ppt","series","escondida","piedritas","motos","western","pueblos","flipper","rompebloques","bloques","feria","amigos","soldados","topo", "cocinando","veoveo", "cadena", "stop", "simon", "mochila", "vistiendo", "muneco", "pool", "metegol", "dinosaurios") and st.get("seats"):
            pid = st.get("turn")
            routed = True
        elif game == "backgammon" and st.get("order"):
            pid = backgammon_current(st)
            routed = True
        elif game == "damas" and st.get("order"):
            pid = damas_current(st)
            routed = True
        elif game in ("patos", "pesca") and st.get("seats"):
            pid = st["seats"][st["turn_idx"] % len(st["seats"])]
            routed = True
    if routed:
        return next((p for p in active if p["id"] == pid), None)
    if room.get("team_count"):
        groups = [[p for p in active if p.get("team") == team] for team in range(room["team_count"])]
        groups = [g for g in groups if g]
        if groups:
            return groups[room["turn"] % len(groups)][(room["turn"] // len(groups)) % len(groups[room["turn"] % len(groups)])]
    return active[room["turn"] % len(active)]


def survivor_winner(room, alive):
    if len(alive) == 1:
        return alive[0]
    if room.get("team_count") and alive and len({p.get("team") for p in alive}) == 1:
        return alive[0]
    return None


