def private_player_state(message, pid):
    state = dict(message)
    views=state.pop("_escondida_views",{})
    if state.get("escondida") and str(pid) in views:state["escondida"]=views[str(pid)]
    tournament=state.get('ppt')
    if tournament:
        # The common projection never includes a pending choice. No per-view answer is needed.
        state['ppt']=dict(tournament)
    cooking=state.get('cocinando')
    if cooking:
        state['cocinando']=dict(cooking,boards=[dict(b,sequence=[],cards=[]) if pid not in b['members'] else b for b in cooking['boards']])
    treasure=state.get('tesoros')
    if treasure:
        state['tesoros']=dict(treasure,result=treasure['result'] if pid in treasure.get('result_members',[]) or treasure['winners'] is not None else '',boards=[dict(b,history=[],visited=[],dug=[],found=[],pos=None,heat=None) if pid not in b['members'] else b for b in treasure['boards']])
    maze=state.get('laberinto')
    if maze:
        state['laberinto']=dict(maze,result=maze['result'] if pid in maze.get('result_members',[]) or maze['winners'] is not None else '',boards=[dict(b,known={},pos=None,heading=None) if pid not in b['members'] else dict(b,known={k:list(v) for k,v in b['known'].items()}) for b in maze['boards']])
    for game in ("cartas", "carrera", "truco", "corazones", "trenes", "poker", "chinchon", "escoba", "uno_oro", "bingo", "escalera", "rosco", "pistas", "oca", "aim", "sapo", "bolos", "hockey", "tejo", "pingpong", "tenis", "ajedrez", "torre", "caballos", "autitos", "aviones", "viborita", "comepuntos", "fantasmas", "castillo", "zombi", "grua", "tesoros","laberinto","ppt","series","escondida","piedritas","motos","western","pueblos","flipper","rompebloques","bloques","feria","amigos","soldados","topo", "cocinando","veoveo", "cadena", "stop", "simon", "mochila", "vistiendo", "muneco", "pool", "metegol", "dinosaurios"):
        data = state.get(game)
        if data and isinstance(data.get("hands"),dict):
            state[game] = dict(data, hands={q: cards for q, cards in data["hands"].items()
                                         if str(q) == str(pid)})
    if state.get("stop"):
        data=state['stop']
        if state.get('phase') not in ('stop_review','stop_result','gameover'):
            owners=[t[0] for t in data['teams'] if pid in t]
            state['stop']=dict(data,sheets={q:b for q,b in data['sheets'].items() if any(str(q)==str(o) for o in owners)})
    if state.get("bingo"):
        data=state["bingo"]
        state["bingo"]=dict(data,marked={q:v for q,v in data.get("marked",{}).items() if str(q)==str(pid)})
    if state.get("escoba"):
        data=state["escoba"]
        state["escoba"]=dict(data,moves={q:v for q,v in data.get("moves",{}).items() if str(q)==str(pid)})
    if state.get("chinchon"):
        data=state["chinchon"]
        state["chinchon"]=dict(data,help={q:v for q,v in data.get("help",{}).items() if str(q)==str(pid)})
    if state.get("flota"):
        data = state["flota"]
        state["flota"] = dict(data, boards={q: board for q, board in data.get("boards", {}).items()
                                            if str(q) == str(pid)})
    return state


async def tell(player, message: dict):
    ws=player.get('ws')
    if ws is None:return
    if message.get('event')=='state':message=private_player_state(message,player['id'])
    lock=player.setdefault('_send_lock',asyncio.Lock())
    async def send():
        async with lock:
            if player.get('ws') is ws:await ws.send_text(json.dumps(message,ensure_ascii=False))
    try:await asyncio.wait_for(send(),WS_SEND_TIMEOUT)
    except Exception:
        # A stalled socket must not clear a newer reconnect or hold everyone up.
        if player.get('ws') is ws:player['ws']=None
        try:await asyncio.wait_for(ws.close(code=1013),.25)
        except Exception:pass


async def broadcast(room, message: dict):
    lock=room.setdefault('_broadcast_lock',asyncio.Lock())
    async with lock:
        await asyncio.gather(*(tell(p,message) for p in list(room['players']) if not p.get('gone')))


_audio_encode_gate = None
_audio_encode_loop = None
_voice_builds = {}

def audio_encode_gate():
    global _audio_encode_gate, _audio_encode_loop
    loop = asyncio.get_running_loop()
    if loop is not _audio_encode_loop:
        _audio_encode_loop = loop
        _audio_encode_gate = asyncio.Semaphore(1)
    return _audio_encode_gate

async def ogg_to_mp3(ogg: bytes) -> bytes:
    """One bounded encoder for the small rehearsal instance, including chat clips."""
    import tempfile
    from pathlib import Path
    async with audio_encode_gate():
        with tempfile.TemporaryDirectory() as directory:
            source = Path(directory) / "in.ogg"
            target = Path(directory) / "out.mp3"
            source.write_bytes(ogg)
            process = await asyncio.create_subprocess_exec(
                "ffmpeg", "-hide_banner", "-loglevel", "error", "-y",
                "-threads", "1", "-filter_threads", "1", "-i", str(source),
                "-af", "loudnorm=I=-16:TP=-1.5:LRA=11", "-threads", "1",
                "-c:a", "libmp3lame", "-b:a", "64k", str(target),
                stdout=asyncio.subprocess.PIPE, stderr=asyncio.subprocess.PIPE,
            )
            try:
                _, stderr = await process.communicate()
            except BaseException:
                # A timeout/cancel must not leave a detached memory-heavy encoder.
                if process.returncode is None:
                    try: process.kill()
                    except ProcessLookupError: pass
                await process.communicate()
                raise
            if process.returncode:
                raise RuntimeError(f"ffmpeg mp3 failed: {stderr.decode()[:300]}")
            return target.read_bytes()


def cache_audio(mp3: bytes) -> str:
    key = hashlib.sha256(mp3).hexdigest()[:24]
    audio_cache[key] = (mp3, time.time())
    for old_key, (_, ts) in list(audio_cache.items()):
        if time.time() - ts > 3600:
            audio_cache.pop(old_key, None)
    # Bound retained audio too; old replay links are best-effort in this rehearsal.
    total = sum(len(item[0]) for item in audio_cache.values())
    while total > 32 * 1024 * 1024 and len(audio_cache) > 1:
        oldest = next(iter(audio_cache))
        total -= len(audio_cache.pop(oldest)[0])
    return key


async def bounded_voice_mp3(text, voice):
    from app import synthesize
    # Identical concurrent private case readings share one synthesis/encode, not data delivery.
    key = (id(asyncio.get_running_loop()), text, voice)
    task = _voice_builds.get(key)
    if task is None or task.done():
        async def build():
            return await ogg_to_mp3(await synthesize(text, voice))
        task = asyncio.create_task(build())
        _voice_builds[key] = task
        def finished(done):
            if _voice_builds.get(key) is done: _voice_builds.pop(key, None)
            if not done.cancelled(): done.exception()
        task.add_done_callback(finished)
    return await asyncio.shield(task)


def narrated_timer(room, coroutine):
    gate = room.get("natural_voice_gate")
    if gate is None or gate.is_set():
        return asyncio.create_task(coroutine)
    state = {"started":False}
    async def run():
        await gate.wait()
        state["started"]=True
        return await coroutine
    task = asyncio.create_task(run())
    def close_unused(_):
        if not state["started"]:coroutine.close()
    task.add_done_callback(close_unused)
    return task


async def wrong_answer_feedback(room, text):
    await broadcast(room, {"event": "answer_feedback", "kind": "wrong"})
    return "Perdiste, no es la correcta. " + text


async def say(room, text: str, voice=None, to=None, question_id=None, rosco_token=None, pistas_token=None, grid_ack=None):
    """Synthesize ONCE server-side and send to everyone (or one player)."""
    from app import synthesize  # local import: app.py mounts this router

    voice = voice or room.get("voice") or "es-AR-ElenaNeural"
    private_campaign = to is not None and room.get('game')=='misterio' and room.get('misterio',{}).get('campaign')
    try:
        task = asyncio.create_task(bounded_voice_mp3(text, voice))
        try:
            mp3 = await asyncio.wait_for(asyncio.shield(task), timeout=4)
        except asyncio.TimeoutError:
            notice = {"event":"voice_wait", "text":"Estoy preparando la voz natural. El reloj de esta pregunta espera la lectura." if question_id is not None else "Estoy preparando la voz natural. Un momento, por favor."}
            if to is not None:
                await tell(to, notice)
            else:
                await broadcast(room, notice)
            try:
                mp3 = await task
            finally:
                if not task.done():
                    task.cancel()
        url = f"/amor-con-aroma-a-cafe/audio/{cache_audio(mp3)}.mp3"
    except Exception:
        log.exception("Web sala: synthesis failed; sending text only")
        url = None
        if not private_campaign:
            gate = room.get("natural_voice_gate")
            if gate is None or gate.is_set():
                room["natural_voice_gate"] = asyncio.Event()
            room["natural_voice_token"] = room.get("natural_voice_token",0) + 1
        notice = {"event":"voice_unavailable", "text":"No se pudo preparar la voz natural. Usá Reintentar voz. No se usará una voz robotizada."}
        targets = [to] if to is not None else connected(room)
        for target in targets:
            target["voice_retry"] = {"text":text,"voice":voice,"question_id":question_id,"rosco_token":rosco_token,"pistas_token":pistas_token,"grid_ack":grid_ack}
        if to is not None:
            await tell(to, notice)
        else:
            await broadcast(room, notice)
    message = {"event": "say", "text": text, "audio": url}
    if url and not private_campaign and room.get("natural_voice_gate") is not None and not room["natural_voice_gate"].is_set():
        message["natural_retry_token"] = room.get("natural_voice_token",0)
        owner=to or current_player(room) or host_player(room)
        if owner and is_game_bot(room,owner["id"]):owner=host_player(room)
        room["natural_voice_gate_owner"]=owner["id"] if owner else None
    if grid_ack is not None:message["grid_ack"]=grid_ack
    if pistas_token is not None:message["pistas_token"]=pistas_token
    if rosco_token is not None:message["rosco_token"]=rosco_token
    if question_id is not None:
        message["question_id"] = question_id
        q = room.get("question")
        if q and q.get("id") == question_id:
            q["audio"] = url
            q["audio_ready"] = True
    if to is not None:
        await tell(to, message)
    else:
        await broadcast(room, message)


async def narrate(room, text: str, voice=None, to=None, question_id=None, rosco_token=None, pistas_token=None, grid_ack=None):
    """Serialized per room so announcements never talk over each other."""
    async with room["audio_lock"]:
        await say(room,text,voice=voice,to=to,question_id=question_id,rosco_token=rosco_token,pistas_token=pistas_token,grid_ack=grid_ack)


