VOF_TOPIC_LABELS = {topic: topic for topic in VOF_BANK}
VOF_TOPICS_TO_PASS = 3


def active_category_labels(room):
    if room.get("game") == "paises":
        return COUNTRY_CATEGORIES
    if room.get("game") == "vof":
        return VOF_TOPIC_LABELS
    return CATEGORIES


COUNTRY_CATEGORIES = {"geografía":"Geografía", "historia":"Historia", "cultura":"Cultura", "comida":"Comida", "películas y series":"Películas y series", "deportes":"Deportes", "ciencia":"Ciencia"}
COUNTRY_MIN_QUESTIONS = 10  # a complete ten-question round without repeated questions


def verified_country_bank(country, category):
    entries = COUNTRY_MC_BANKS.get(country, {}).get(category, [])
    result = []
    seen = set()
    for item in entries:
        if (not isinstance(item, dict) or item.get("verified") is not True
                or item.get("country") != country or item.get("category") != category
                or not str(item.get("source_url", "")).startswith("https://")):
            continue
        q, options, answer = item.get("q"), item.get("options"), item.get("answer")
        if (not isinstance(q, str) or not q.strip() or q in seen
                or not isinstance(options, list) or len(options) != 4
                or len(set(options)) != 4 or not all(isinstance(x, str) and x.strip() for x in options)
                or not isinstance(answer, int) or isinstance(answer, bool) or answer not in range(4)):
            continue
        seen.add(q)
        result.append((q, options[:], answer))
    return result


def covered_country_categories(country):
    return [cat for cat in COUNTRY_CATEGORIES if country in COUNTRY_DESTINATIONS and len(verified_country_bank(country, cat)) >= COUNTRY_MIN_QUESTIONS]


async def country_content_missing(room, player):
    cancel_timer(room)
    room["spinning"] = False
    room["question"] = None
    room["phase"] = "country_content_missing"
    await broadcast(room, room_state(room))
    await narrate(room, f"{player['name']}, todavía no hay preguntas verificadas suficientes para este país y categoría. "
                  "No vamos a darte preguntas generales como si fueran de ese país. No perdés vidas. "
                  "Podés salir de este juego y elegir otro mientras completamos el banco.")



def player_difficulty(player):
    return difficulty_rules.level((player or {}).get('difficulty'))


def bot_difficulty_level(room):
    humans=[p for p in room.get('players',[]) if not p.get('gone') and not p.get('spectator')]
    return player_difficulty(humans[0]) if humans else 'normal'


def scaled_bot_move(room,best,moves):
    chosen=bot_difficulty_level(room)
    if chosen is None or not moves or random.random()<difficulty_rules.skill(chosen):return best
    return random.choice(moves)


def scaled_bot_delay(room,base=1):
    chosen=bot_difficulty_level(room)
    return difficulty_rules.delay(chosen) if chosen is not None else base


def participant_level(room,pid):
    player=next((p for p in room.get('players',[]) if p['id']==pid),None)
    return bot_difficulty_level(room) if is_game_bot(room,pid) else player_difficulty(player)


def participant_seconds(room,pid,base):
    return difficulty_rules.seconds(participant_level(room,pid),base)


def room_question_level(room):
    return player_difficulty(current_player(room)) if room.get('players') else 'normal'


def difficulty_question_pool(room,bank,available,text=lambda item:item[0]):
    pool=difficulty_rules.question_pool(bank,available,room_question_level(room),text)
    return pool


async def set_difficulty(room,player,value):
    parsed=difficulty_rules.parse(value)
    if parsed is None:return False
    player['difficulty']=parsed
    await narrate(room,'Dificultad '+difficulty_rules.name(parsed)+'. Se guarda para vos y se aplica desde el próximo turno o pregunta. Las preguntas tienen clasificación automática inicial, todavía no calibrada.',to=player)
    await broadcast(room,room_state(room));return True


def presentation_choice(text):
    value=norm(text)
    if value in ('imagenes y narracion','imagenes mas narracion','ver imagenes y escuchar','imagenes con narracion'):return 'both'
    if value in ('solo imagenes','sin narracion'):return 'images'
    if value in ('solo audio','no ver imagenes','sin imagenes'):return 'audio'
    return None


@router.post('/amor-con-aroma-a-cafe/api/presentacion-voz')
async def presentation_voice_clip(request: Request):
    body=await request.body()
    if not body or len(body)>3_000_000:return Response(status_code=400)
    text=await transcribe_clip(body);mode=presentation_choice(text or '')
    return {'heard':mode is not None,'presentation':mode,'text':text}


@router.post('/amor-con-aroma-a-cafe/api/dificultad-voz')
async def difficulty_voice_clip(request: Request):
    body=await request.body()
    if not body or len(body)>3_000_000:return Response(status_code=400)
    text=await transcribe_clip(body)
    chosen=difficulty_rules.parse(text or '')
    return {'heard':chosen is not None,'difficulty':chosen,'text':text}


