def origin_choice(value):
    return value if isinstance(value,str) and value in COUNTRY_DESTINATIONS else ""

def joined_text(player,count):
    origin=origin_choice(player.get('origin'))
    return (f"Se sumó {player['name']} de {origin}" if origin else f"Se unió {player['name']}")+f". Ahora son {count} en la sala."

AH_INVITATIONS = ["¡Vamos a jugar al ahorcado, {name}!", "Dale, {name}, vamos a entrar a ver algo lindo. La palabra nos espera.", "¡Vengan a jugar al ahorcado! {name} ya está en la mesa.", "Tenemos letras, pistas y una mesa para compartir. ¡Vamos, {name}!"]

async def ah_invite(room):
    player=host_player(room)
    if player:await narrate(room,random.choice(AH_INVITATIONS).format(name=player['name']))

async def ah_lobby_invites(room):
    try:
        while room['phase']=='lobby' and room['game']=='ahorcado':
            await asyncio.sleep(12)
            if room['phase']!='lobby':return
            if not room['audio_lock'].locked() and room.get('mic_until',0)<=asyncio.get_running_loop().time():await ah_invite(room)
    except asyncio.CancelledError:pass


def chatter_voice(room):
    idx = room.get("chatter_idx", 0)
    room["chatter_idx"] = idx + 1
    return CHATTER_VOICES[idx % len(CHATTER_VOICES)]


async def turn_chatter(room, player):
    # Ephemeral prompts: never queue them behind an important announcement.
    if room["audio_lock"].locked() or room.get("mic_until", 0) > asyncio.get_running_loop().time():
        return
    async with room["audio_lock"]:
        voice = chatter_voice(room)
        lines = {
            "es-AR-ElenaNeural": ["Dale, {name}, vos podés.", "Che, {name}, ¡el reloj corre!"],
            "es-AR-TomasNeural": ["Vamos, {name}, ¡a jugar!", "Dale, {name}, ¡no te duermas!"],
            "es-UY-ValentinaNeural": ["Bo, {name}, ¡metele!", "Vamos arriba, {name}."],
            "es-MX-DaliaNeural": ["Órale, {name}, ¡tú puedes!", "Ánimo, {name}, ¡ya casi!"],
            "es-CO-GonzaloNeural": ["¡Qué más, {name}! Dale con toda.", "Vamos, {name}, ¡tú puedes!"],
            "es-CL-CatalinaNeural": ["¡Vamos, {name}, al tiro!", "Dale, {name}, ¡qué buena onda!"],
        }
        origin=origin_choice(player.get("origin"))
        pool=ORIGIN_CHATTER.get(origin) or (['Vamos, {name}, ¡a jugar! '+origin+' presente en esta mesa.'] if origin else lines[voice])
        text = random.choice(pool).format(name=player["name"])
        from app import synthesize
        try:
            data = await asyncio.wait_for(ogg_to_mp3(await synthesize(text, voice)), timeout=3)
        except Exception:
            log.exception("Chatter synthesis failed")
            return
        if room.get("mic_until", 0) > asyncio.get_running_loop().time():
            return
        await broadcast(room, {"event": "chatter", "text": text,
                              "audio": f"/amor-con-aroma-a-cafe/audio/{cache_audio(data)}.mp3" if data else None})



# ---------------------------------------------------------------------------
# Siete y medio: manos contra la banca con mazo español de 40 cartas.
# Sota, caballo y rey valen medio punto. Sin eliminación: a cero vidas se
# vuelve a empezar con tres. El primero en juntar WIN_SCORE puntos gana.
# ---------------------------------------------------------------------------
SIETE_LIVES = 3
SIETE_PALOS = ("oros", "copas", "espadas", "bastos")
SIETE_FIGURES = {"sota": "la sota", "caballo": "el caballo", "rey": "el rey"}
SIETE_NUMBERS = {1: "el as", 2: "el dos", 3: "el tres", 4: "el cuatro",
                 5: "el cinco", 6: "el seis", 7: "el siete"}


def siete_new_deck():
    deck = [(rank, palo) for rank in range(1, 8) for palo in SIETE_PALOS]
    deck += [(fig, palo) for fig in SIETE_FIGURES for palo in SIETE_PALOS]
    random.shuffle(deck)
    return deck


def siete_card_value(card):
    rank, _ = card
    return rank if isinstance(rank, int) else 0.5


def siete_card_name(card):
    rank, palo = card
    name = SIETE_NUMBERS[rank] if isinstance(rank, int) else SIETE_FIGURES[rank]
    return f"{name} de {palo}"


def siete_total(cards):
    return sum(siete_card_value(c) for c in cards)


def siete_total_text(total):
    return f"{int(total)} y medio" if total % 1 else str(int(total))


def siete_parse_move(text):
    t = (text or "").lower()
    if any(w in t for w in ("carta", "otra", "dame", "pedí", "pedime", "dale")):
        return "carta"
    if any(w in t for w in ("planto", "planta", "basta", "paro", "quedo")):
        return "planto"
    return None


def new_siete():
    return {"deck": siete_new_deck(), "hand": None, "lives": {}}


def siete_draw(room):
    st = room["siete"]
    if len(st["deck"]) < 8:
        st["deck"] = siete_new_deck()
    return st["deck"].pop()


def siete_state(room):
    st = room.get("siete") or {}
    hand = st.get("hand")
    return {
        "cards": [siete_card_name(c) for c in hand["cards"]] if hand else [],
        "total": siete_total_text(siete_total(hand["cards"])) if hand else "",
        "house_cards": [siete_card_name(c) for c in hand.get("house", [])] if hand else [],
        "lives": st.get("lives", {}),
        "target": WIN_SCORE,
    }


async def siete_start_hand(room, player):
    st = room["siete"]
    st["lives"].setdefault(player["id"], SIETE_LIVES)
    card = siete_draw(room)
    st["hand"] = {"player": player["id"], "cards": [card], "house": []}
    room["phase"] = "siete"
    total = siete_total_text(siete_total(st["hand"]["cards"]))
    await narrate(room, f"{player['name']}, jugás esta mano contra la banca. Salió {siete_card_name(card)}: "
                        f"tenés {total}. ¿Carta o te plantás?")
    await broadcast(room, room_state(room))
    await tell(player, {"event": "your_turn", "kind": "siete"})


async def siete_move(room, player, move):
    st = room.get("siete")
    hand = st and st.get("hand")
    if room["phase"] != "siete" or not hand or hand["player"] != player["id"]:
        return
    cancel_timer(room)
    if move == "carta":
        card = siete_draw(room)
        hand["cards"].append(card)
        total = siete_total(hand["cards"])
        name = siete_card_name(card)
        if total > 7.5:
            room["phase"] = "siete_resolve"
            lives = st["lives"].get(player["id"], SIETE_LIVES) - 1
            st["lives"][player["id"]] = lives
            await narrate(room, f"{name}. Te pasaste con {siete_total_text(total)}: perdés una vida, "
                                f"te quedan {['cero', 'una', 'dos', 'tres'][lives]}.")
            await broadcast(room, room_state(room))
            if lives <= 0:
                st["lives"][player["id"]] = SIETE_LIVES
                await narrate(room, f"{player['name']}, sin vidas: volvés a empezar con tres.")
            await end_turn(room)
            return
        if total == 7.5:
            room["phase"] = "siete_resolve"
            natural = len(hand["cards"]) == 2
            points = 2 if natural else 1
            score = room["scores"].get(player["id"], 0) + points
            sync_score(room, player, score)
            await narrate(room, f"¡{name}! ¡Siete y medio{' justo, con dos cartas' if natural else ''}! "
                                f"{'Valen dos puntos' if natural else 'Vale un punto'} para {player['name']}, que llega a {score}.")
            await broadcast(room, room_state(room))
            await end_turn(room)
            return
        await narrate(room, f"{name}. Tenés {siete_total_text(total)}. ¿Carta o te plantás?")
        await broadcast(room, room_state(room))
        room["timer_task"] = narrated_timer(room,turn_clock(room, player["id"]))
        return
    room["phase"] = "siete_resolve"
    total = siete_total(hand["cards"])
    house = []
    house_total = 0
    while house_total < 5.5:
        house.append(siete_draw(room))
        house_total = siete_total(house)
    hand["house"] = house
    house_cards = ", ".join(siete_card_name(c) for c in house)
    await narrate(room, f"{player['name']} se planta con {siete_total_text(total)}. "
                        f"Juega la banca: {house_cards}. La banca tiene {siete_total_text(house_total)}.")
    if house_total > 7.5:
        score = room["scores"].get(player["id"], 0) + 1
        sync_score(room, player, score)
        await narrate(room, f"La banca se pasó. Punto para {player['name']}, que lleva {score}.")
    elif house_total > total:
        await narrate(room, f"Gana la banca con {siete_total_text(house_total)}. Sin punto esta vez.")
    elif house_total == total:
        await narrate(room, f"Empate en {siete_total_text(total)}. Sin punto para nadie.")
    else:
        score = room["scores"].get(player["id"], 0) + 1
        sync_score(room, player, score)
        await narrate(room, f"Le ganás a la banca {siete_total_text(total)} a {siete_total_text(house_total)}. "
                            f"Punto para {player['name']}, que lleva {score}.")
    await broadcast(room, room_state(room))
    await end_turn(room)



# ---------------------------------------------------------------------------
# Tatetí: tres en línea con casillas 1 a 9. Solo contra la app o 1 vs 1 en
# sala. El primer jugador elige cruz o círculo; las cruces empiezan.
# Serie: el primero en ganar TATETI_WINS juegos gana la partida.
# ---------------------------------------------------------------------------
TATETI_WINS = 3
TATETI_LINES = [(0, 1, 2), (3, 4, 5), (6, 7, 8),
                (0, 3, 6), (1, 4, 7), (2, 5, 8),
                (0, 4, 8), (2, 4, 6)]
TATETI_CORNERS = [0, 2, 6, 8]



CARTAS_COLORS = ["rojo", "azul", "verde", "amarillo"]
CARTAS_NUMS = ["uno", "dos", "tres", "cuatro", "cinco", "seis", "siete", "ocho", "nueve"]
CARTAS_HAND = 7


def cartas_new_deck():
    deck = [(c, n) for c in CARTAS_COLORS for n in CARTAS_NUMS for _ in range(2)]
    deck += [(c, "salta") for c in CARTAS_COLORS for _ in range(2)]
    deck += [(c, "toma dos") for c in CARTAS_COLORS for _ in range(2)]
    deck += [("comodin", "comodin") for _ in range(4)]
    random.shuffle(deck)
    return deck


def cartas_card_name(card):
    color, value = card
    if color == "comodin":
        return "el comodín"
    if value == "salta":
        return f"el salta {color}"
    if value == "toma dos":
        return f"el toma dos {color}"
    return f"el {color} {value}"


def cartas_playable(card, top, chosen):
    if card[0] == "comodin":
        return True
    return card[0] == (chosen or top[0]) or card[1] == top[1]


def cartas_parse_color(text):
    tokens = norm(text).split()
    for c in CARTAS_COLORS:
        if c in tokens:
            return c
    return None


def cartas_parse_play(text, hand):
    t = norm(text)
    tokens = t.split()
    if "comodin" in tokens and ("comodin", "comodin") in hand:
        return ("play", ("comodin", "comodin"))
    color = cartas_parse_color(t)
    value = None
    if "salta" in tokens:
        value = "salta"
    elif "toma" in tokens and "dos" in tokens:
        value = "toma dos"
    else:
        for i, n in enumerate(CARTAS_NUMS, 1):
            if n in tokens or str(i) in tokens:
                value = n
                break
    if color and value and (color, value) in hand:
        return ("play", (color, value))
    if any(w in tokens for w in ("robo", "robar", "levanto", "levantar", "paso", "carta")):
        return ("draw",)
    return None


def new_cartas(room):
    ids = [p["id"] for p in room["players"] if not p.get("gone") and not p.get("spectator")]
    vs_app = len(ids) == 1
    order = ids + (["app"] if vs_app else [])
    st = {"deck": cartas_new_deck(), "order": order, "idx": 0,
          "hands": {pid: [] for pid in order}, "top": None, "color": None,
          "vs_app": vs_app, "winner": None}
    for _ in range(CARTAS_HAND):
        for pid in order:
            st["hands"][pid].append(st["deck"].pop())
    while True:
        top = st["deck"].pop()
        if top[0] != "comodin" and top[1] not in ("salta", "toma dos"):
            st["top"] = top
            break
        st["deck"].insert(0, top)
    return st


def cartas_state(room):
    st = room.get("cartas") or {}
    return {
        "top": cartas_card_name(st["top"]) if st.get("top") else "",
        "color": st.get("color"),
        "hands": {pid: [cartas_card_name(c) for c in cards] for pid, cards in st.get("hands", {}).items()},
        "counts": {pid: len(cards) for pid, cards in st.get("hands", {}).items()},
        "current": st["order"][st["idx"]] if st.get("order") else "",
        "winner": st.get("winner"),
    }


def is_game_bot(room, pid):
    return (isinstance(pid, str) and pid.startswith("app")) or pid in room.get("bot_seats", [])


def cartas_actor_name(room, pid):
    if pid in room.get("bot_names", {}):
        return room["bot_names"][pid]
    if pid == "app":
        return "la app"
    p = next((q for q in room["players"] if q["id"] == pid), None)
    return p["name"] if p else "alguien"


def cartas_draw_cards(st, pid, n=1):
    drawn = []
    for _ in range(n):
        if not st["deck"]:
            st["deck"] = cartas_new_deck()
        drawn.append(st["deck"].pop())
    st["hands"][pid].extend(drawn)
    return drawn


async def cartas_turn(room):
    st = room["cartas"]
    if st.get("winner"):
        return
    pid = st["order"][st["idx"]]
    if is_game_bot(room, pid):
        room["phase"] = "cartas"
        await broadcast(room, room_state(room))
        await asyncio.sleep(scaled_bot_delay(room,2))
        await cartas_app_play(room)
        return
    player = next(p for p in room["players"] if p["id"] == pid)
    room["phase"] = "cartas"
    hand_txt = ", ".join(cartas_card_name(c) for c in st["hands"][pid])
    await narrate(room, f"Tenés: {hand_txt}.", to=player)
    extra = f" y vale el color {st['color']}" if st["color"] else ""
    await narrate(room, f"{player['name']}, tu turno: la mesa tiene {cartas_card_name(st['top'])}{extra}. "
                        f"Jugá una carta del mismo color o valor, un comodín, o decí «robo».")
    await broadcast(room, room_state(room))
    await tell(player, {"event": "your_turn", "kind": "cartas"})
    room["timer_task"] = narrated_timer(room,turn_clock(room, pid))


async def cartas_finish(room, winner):
    st = room["cartas"]
    st["winner"] = winner
    cancel_timer(room)
    await broadcast(room, room_state(room))
    if is_game_bot(room, winner):
        await narrate(room, "¡Me quedé sin cartas! Gané yo esta vez. Vamos de nuevo, que hay revancha.")
        room["cartas"] = new_cartas(room)
        await cartas_turn(room)
        return
    player = next(p for p in room["players"] if p["id"] == winner)
    await game_over(room, player)


async def cartas_apply_card(room, pid, card):
    st = room["cartas"]
    name = cartas_card_name(card)
    actor = cartas_actor_name(room, pid)
    st["hands"][pid].remove(card)
    st["top"] = card
    st["color"] = None
    if not st["hands"][pid]:
        await narrate(room, f"{actor} juega {name} y se queda sin cartas.")
        await cartas_finish(room, pid)
        return
    skip = 1
    if card[1] == "salta":
        nxt = st["order"][(st["idx"] + 1) % len(st["order"])]
        await narrate(room, f"{actor} juega {name}: {cartas_actor_name(room, nxt)} pierde el turno.")
        skip = 2
    elif card[1] == "toma dos":
        nxt = st["order"][(st["idx"] + 1) % len(st["order"])]
        cartas_draw_cards(st, nxt, 2)
        await narrate(room, f"{actor} juega {name}: {cartas_actor_name(room, nxt)} levanta dos cartas y pierde el turno.")
        skip = 2
    else:
        await narrate(room, f"{actor} juega {name}.")
    st["idx"] = (st["idx"] + skip) % len(st["order"])
    await cartas_turn(room)


async def cartas_play(room, player, card):
    st = room.get("cartas")
    if not st or room["phase"] != "cartas" or st.get("winner"):
        return
    if st["order"][st["idx"]] != player["id"] or card not in st["hands"][player["id"]]:
        return
    if not cartas_playable(card, st["top"], st["color"]):
        await narrate(room, f"{player['name']}, esa no va: tiene que coincidir en color o en valor, "
                            f"o ser un comodín.", to=player)
        return
    cancel_timer(room)
    if card[0] == "comodin":
        st["hands"][player["id"]].remove(card)
        st["top"] = card
        st["color"] = None
        if not st["hands"][player["id"]]:
            await narrate(room, f"{player['name']} juega el comodín y se queda sin cartas.")
            await cartas_finish(room, player["id"])
            return
        room["phase"] = "cartas_color"
        await narrate(room, f"{player['name']} juega el comodín. Elegí color: rojo, azul, verde o amarillo.")
        await tell(player, {"event": "your_turn", "kind": "cartas_color"})
        await broadcast(room, room_state(room))
        room["timer_task"] = narrated_timer(room,turn_clock(room, player["id"]))
        return
    await cartas_apply_card(room, player["id"], card)


async def cartas_choose_color(room, player, color):
    st = room.get("cartas")
    if not st or room["phase"] != "cartas_color" or color not in CARTAS_COLORS:
        return
    if st["order"][st["idx"]] != player["id"]:
        return
    cancel_timer(room)
    st["color"] = color
    await narrate(room, f"{player['name']} pide el color {color}.")
    st["idx"] = (st["idx"] + 1) % len(st["order"])
    await cartas_turn(room)


async def cartas_draw(room, player):
    st = room.get("cartas")
    if not st or room["phase"] != "cartas" or st.get("winner"):
        return
    if st["order"][st["idx"]] != player["id"]:
        return
    cancel_timer(room)
    drawn = cartas_draw_cards(st, player["id"], 1)
    await narrate(room, f"{player['name']} levanta una carta y pasa.")
    await narrate(room, f"Levantaste {cartas_card_name(drawn[0])}.", to=player)
    st["idx"] = (st["idx"] + 1) % len(st["order"])
    await cartas_turn(room)


async def cartas_app_play(room):
    st = room["cartas"]
    pid = st["order"][st["idx"]]
    if st.get("winner"):
        return
    hand = st["hands"][pid]
    legal = [c for c in hand if cartas_playable(c, st["top"], st["color"])]
    if not legal:
        cartas_draw_cards(st, pid, 1)
        await narrate(room, "Levanto una carta y paso.")
        st["idx"] = (st["idx"] + 1) % len(st["order"])
        await cartas_turn(room)
        return
    nums = [c for c in legal if c[0] != "comodin" and c[1] not in ("salta", "toma dos")]
    card = scaled_bot_move(room,nums[0] if nums else legal[0],legal)
    if card[0] == "comodin":
        counts = {c: sum(1 for x in hand if x[0] == c) for c in CARTAS_COLORS}
        hand.remove(card)
        st["top"] = card
        st["color"] = None
        if not hand:
            await narrate(room, "Juego el comodín y me quedo sin cartas.")
            await cartas_finish(room, pid)
            return
        st["color"] = scaled_bot_move(room,max(CARTAS_COLORS, key=lambda c: counts[c]),list(CARTAS_COLORS))
        await narrate(room, f"Juego el comodín y pido el color {st['color']}.")
        st["idx"] = (st["idx"] + 1) % len(st["order"])
        await cartas_turn(room)
        return
    await cartas_apply_card(room, pid, card)



CARRERA_META = 1000
CARRERA_HAND = 6
CARRERA_FIX = {"pinchadura": "auxilio", "sin nafta": "nafta", "choque": "reparación",
               "semáforo rojo": "verde", "límite": "fin de límite"}


def carrera_new_deck():
    deck = [("km", 25)] * 10 + [("km", 50)] * 10 + [("km", 75)] * 10 + [("km", 100)] * 12 + [("km", 200)] * 4
    deck += [("luz", "verde")] * 14
    deck += [("hazard", "pinchadura")] * 3 + [("hazard", "sin nafta")] * 3 + [("hazard", "choque")] * 1
    deck += [("hazard", "semáforo rojo")] * 4 + [("hazard", "límite")] * 3
    deck += [("remedy", "auxilio")] * 6 + [("remedy", "nafta")] * 6 + [("remedy", "reparación")] * 6
    deck += [("remedy", "fin de límite")] * 6
    random.shuffle(deck)
    return deck


def carrera_card_name(card):
    kind, value = card
    if kind == "km":
        nombres = {25: "veinticinco", 50: "cincuenta", 75: "setenta y cinco", 100: "cien", 200: "doscientos"}
        return f"{nombres[value]} kilómetros"
    if kind == "luz":
        return "luz verde"
    if kind == "hazard":
        return {"pinchadura": "pinchadura", "sin nafta": "sin nafta", "choque": "choque",
                "semáforo rojo": "semáforo rojo", "límite": "límite de velocidad"}[value]
    return {"auxilio": "rueda de auxilio", "nafta": "nafta", "reparación": "reparación",
            "fin de límite": "fin de límite"}[value]


def carrera_driving(st, pid):
    return st["verde"].get(pid) and not st["hazard"].get(pid)


def new_carrera(room):
    ids = [p["id"] for p in room["players"] if not p.get("gone") and not p.get("spectator")]
    vs_app = len(ids) == 1
    order = ids + (["app"] if vs_app else [])
    st = {"deck": carrera_new_deck(), "order": order, "idx": 0,
          "hands": {pid: [] for pid in order}, "km": {pid: 0 for pid in order},
          "verde": {pid: False for pid in order}, "hazard": {pid: None for pid in order},
          "limit": {pid: False for pid in order}, "vs_app": vs_app, "winner": None, "discard": []}
    for _ in range(CARRERA_HAND):
        for pid in order:
            st["hands"][pid].append(st["deck"].pop())
    return st


def carrera_estado_text(st, pid):
    partes = []
    if st["hazard"].get(pid):
        partes.append(f"frenado por {st['hazard'][pid]}")
    elif st["verde"].get(pid):
        partes.append("en marcha")
    else:
        partes.append("parado, necesita luz verde")
    if st["limit"].get(pid):
        partes.append("con límite de velocidad")
    return ", ".join(partes)


def carrera_state(room):
    st = room.get("carrera") or {}
    return {
        "km": st.get("km", {}),
        "estado": {pid: carrera_estado_text(st, pid) for pid in st.get("order", [])},
        "hands": {pid: [carrera_card_name(c) for c in cards] for pid, cards in st.get("hands", {}).items()},
        "counts": {pid: len(cards) for pid, cards in st.get("hands", {}).items()},
        "current": st["order"][st["idx"]] if st.get("order") else "",
        "winner": st.get("winner"),
        "meta": CARRERA_META,
    }


def carrera_actor_name(room, pid):
    return cartas_actor_name(room, pid)


def carrera_draw_one(st, pid):
    if st["deck"]:
        st["hands"][pid].append(st["deck"].pop())


def carrera_parse_play(text, hand):
    t = norm(text)
    tokens = t.split()
    discard = any(w in tokens for w in ("descarto", "descartar", "tiro", "descarta"))
    card = None
    if "sin" in tokens and "nafta" in tokens:
        card = ("hazard", "sin nafta")
    elif "fin" in tokens and ("limite" in tokens or "límite" in tokens):
        card = ("remedy", "fin de límite")
    elif "pinchadura" in tokens:
        card = ("hazard", "pinchadura")
    elif "choque" in tokens or "accidente" in tokens:
        card = ("hazard", "choque")
    elif "rojo" in tokens or "semaforo" in tokens:
        card = ("hazard", "semáforo rojo")
    elif "limite" in tokens:
        card = ("hazard", "límite")
    elif "auxilio" in tokens or "rueda" in tokens:
        card = ("remedy", "auxilio")
    elif "nafta" in tokens or "combustible" in tokens:
        card = ("remedy", "nafta")
    elif "reparacion" in tokens or "arreglo" in tokens or "reparar" in tokens:
        card = ("remedy", "reparación")
    elif "verde" in tokens or "arranco" in tokens or "arrancar" in tokens:
        card = ("luz", "verde")
    else:
        for words, km in ((("veinticinco", "25"), 25), (("cincuenta", "50"), 50),
                          (("setenta", "75"), 75), (("cien", "cien", "100"), 100),
                          (("doscientos", "200"), 200)):
            if any(w in tokens for w in words):
                card = ("km", km)
                break
    if card is None or card not in hand:
        return None
    return ("discard", card) if discard else ("play", card)


async def carrera_turn(room):
    st = room["carrera"]
    if st.get("winner"):
        return
    pid = st["order"][st["idx"]]
    if is_game_bot(room, pid):
        room["phase"] = "carrera"
        await broadcast(room, room_state(room))
        await asyncio.sleep(scaled_bot_delay(room,2))
        await carrera_app_play(room)
        return
    player = next(p for p in room["players"] if p["id"] == pid)
    room["phase"] = "carrera"
    hand_txt = ", ".join(carrera_card_name(c) for c in st["hands"][pid])
    await narrate(room, f"Tenés: {hand_txt}.", to=player)
    rival = next(x for x in st["order"] if x != pid)
    await narrate(room, f"{player['name']}, tu turno. Llevás {st['km'][pid]} de {CARRERA_META} kilómetros "
                        f"({carrera_estado_text(st, pid)}). {carrera_actor_name(room, rival)} lleva "
                        f"{st['km'][rival]}. Jugá una carta o descartá una.")
    await broadcast(room, room_state(room))
    await tell(player, {"event": "your_turn", "kind": "carrera"})
    room["timer_task"] = narrated_timer(room,turn_clock(room, pid))


async def carrera_finish(room, winner):
    st = room["carrera"]
    st["winner"] = winner
    cancel_timer(room)
    await broadcast(room, room_state(room))
    if is_game_bot(room, winner):
        await narrate(room, f"¡Llegué a los {CARRERA_META} kilómetros primero! Gané yo. ¿Revancha? Arrancamos.")
        room["carrera"] = new_carrera(room)
        await carrera_turn(room)
        return
    player = next(p for p in room["players"] if p["id"] == winner)
    await game_over(room, player)


async def carrera_apply(room, pid, card, discard=False):
    st = room["carrera"]
    actor = carrera_actor_name(room, pid)
    st["hands"][pid].remove(card)
    name = carrera_card_name(card)
    if discard:
        st["discard"].append(card)
        await narrate(room, f"{actor} descarta {name}.")
    else:
        kind, value = card
        if kind == "km":
            st["km"][pid] += value
            await narrate(room, f"{actor} avanza {name}: lleva {st['km'][pid]} de {CARRERA_META}.")
        elif kind == "luz":
            st["verde"][pid] = True
            if st["hazard"].get(pid) == "semáforo rojo":
                st["hazard"][pid] = None
            await narrate(room, f"{actor} tiene luz verde: ¡en marcha!")
        elif kind == "hazard":
            rival = next(x for x in st["order"] if x != pid)
            if value == "límite":
                st["limit"][rival] = True
            else:
                st["hazard"][rival] = value
            await narrate(room, f"{actor} le juega {name} a {carrera_actor_name(room, rival)}.")
        else:
            if value == "fin de límite":
                st["limit"][pid] = False
            else:
                st["hazard"][pid] = None
            await narrate(room, f"{actor} se arregla con {name}.")
    if st["km"][pid] >= CARRERA_META and not discard:
        await carrera_finish(room, pid)
        return
    carrera_draw_one(st, pid)
    st["idx"] = (st["idx"] + 1) % len(st["order"])
    await carrera_turn(room)


def carrera_legal(room, pid, card):
    st = room["carrera"]
    kind, value = card
    if kind == "km":
        if not carrera_driving(st, pid):
            return "no estás en marcha: necesitás luz verde y estar sin problemas"
        if st["limit"].get(pid) and value > 50:
            return "con límite de velocidad solo podés avanzar de a 25 o 50"
        return None
    if kind == "luz":
        if carrera_driving(st, pid):
            return "ya estás en marcha"
        return None
    if kind == "hazard":
        rival = next(x for x in st["order"] if x != pid)
        if value == "límite":
            if st["limit"].get(rival):
                return f"{carrera_actor_name(room, rival)} ya tiene límite de velocidad"
            if not st["verde"].get(rival):
                return f"{carrera_actor_name(room, rival)} todavía no arrancó"
            return None
        if not carrera_driving(st, rival):
            return f"{carrera_actor_name(room, rival)} no está en marcha"
        return None
    if value == "fin de límite":
        if not st["limit"].get(pid):
            return "no tenés límite de velocidad"
        return None
    if st["hazard"].get(pid) != value and CARRERA_FIX.get(st["hazard"].get(pid)) != value:
        return f"no tenés ese problema ahora"
    return None


async def carrera_play(room, player, card, discard=False):
    st = room.get("carrera")
    if not st or room["phase"] != "carrera" or st.get("winner"):
        return
    if st["order"][st["idx"]] != player["id"] or card not in st["hands"][player["id"]]:
        return
    if not discard:
        why = carrera_legal(room, player["id"], card)
        if why:
            await narrate(room, f"{player['name']}, no podés jugar esa: {why}.", to=player)
            return
    cancel_timer(room)
    await carrera_apply(room, player["id"], card, discard=discard)


def carrera_app_pick(st, pid="app"):
    hand = st["hands"][pid]
    rival = next(x for x in st["order"] if x != pid)
    hz = st["hazard"].get(pid)
    if hz:
        fix = ("remedy", CARRERA_FIX[hz]) if hz != "límite" else ("remedy", "fin de límite")
        if fix in hand:
            return ("play", fix)
    if st["limit"].get(pid) and ("remedy", "fin de límite") in hand:
        return ("play", ("remedy", "fin de límite"))
    if not st["verde"].get(pid) and ("luz", "verde") in hand:
        return ("play", ("luz", "verde"))
    if carrera_driving(st, pid):
        kms = [c for c in hand if c[0] == "km" and not (st["limit"].get(pid) and c[1] > 50)]
        if kms:
            return ("play", max(kms, key=lambda c: c[1]))
    if carrera_driving(st, rival):
        hazards = [c for c in hand if c[0] == "hazard" and not (c[1] == "límite" and st["limit"].get(rival))]
        if hazards:
            return ("play", hazards[0])
    for useless in ([c for c in hand if c[0] == "hazard"] + [c for c in hand if c[0] == "km"] + hand):
        return ("discard", useless)
    return ("discard", hand[0])


async def carrera_app_play(room):
    st = room["carrera"]
    pid = st["order"][st["idx"]]
    if st.get("winner"):
        return
    hand = st["hands"][pid]
    if not hand:
        st["idx"] = (st["idx"] + 1) % len(st["order"])
        await carrera_turn(room)
        return
    options=[("play",c) for c in hand if carrera_legal(room,pid,c) is None]+[("discard",c) for c in hand]
    action, card = scaled_bot_move(room,carrera_app_pick(st, pid),options)
    if action == "play":
        why = carrera_legal(room, pid, card)
        if why:
            action, card = "discard", card
    await carrera_apply(room, pid, card, discard=(action == "discard"))



FLOTA_LETRAS = ["A", "B", "C", "D", "E", "F", "G", "H"]
FLOTA_TAMANOS = [4, 3, 2]
FLOTA_NOMBRES = {4: "el barco grande", 3: "el barco mediano", 2: "el barco chico"}


def flota_coord_name(cell):
    col, row = cell
    letras = {"A": "A", "B": "B", "C": "C", "D": "D", "E": "E", "F": "F", "G": "G", "H": "H"}
    return f"{letras[col]} {row}"


def flota_new_fleet():
    ships = []
    ocupadas = set()
    for tam in FLOTA_TAMANOS:
        while True:
            horizontal = random.random() < 0.5
            c = random.randrange(0, 8 - (tam - 1 if horizontal else 0))
            r = random.randrange(1, 9 - (0 if horizontal else tam - 1))
            celdas = [(FLOTA_LETRAS[c + i], r) if horizontal else (FLOTA_LETRAS[c], r + i) for i in range(tam)]
            if not any(celda in ocupadas for celda in celdas):
                ships.append(celdas)
                ocupadas.update(celdas)
                break
    return ships


def new_flota(room):
    ids = [p["id"] for p in room["players"] if not p.get("gone") and not p.get("spectator")]
    vs_app = len(ids) == 1
    order = ids + (["app"] if vs_app else [])
    return {"order": order, "idx": 0, "vs_app": vs_app, "winner": None,
            "ships": {pid: flota_new_fleet() for pid in order},
            "shots": {pid: {} for pid in order},
            "target": {pid: [] for pid in order}}


def flota_parse_coord(text):
    t = norm(text)
    tokens = t.split()
    for tok in tokens:
        if len(tok) == 2 and tok[0] in "abcdefgh" and tok[1] in "12345678":
            return (tok[0].upper(), int(tok[1]))
    col = None
    letras = {"a": "A", "be": "B", "b": "B", "ce": "C", "c": "C", "de": "D", "d": "D",
              "e": "E", "efe": "F", "f": "F", "ge": "G", "g": "G", "hache": "H", "h": "H"}
    for tok in tokens:
        if tok in letras:
            col = letras[tok]
            break
    if col is None:
        return None
    row = None
    nums = {"uno": 1, "dos": 2, "tres": 3, "cuatro": 4, "cinco": 5, "seis": 6, "siete": 7, "ocho": 8}
    for tok in tokens:
        if tok.isdigit() and 1 <= int(tok) <= 8:
            row = int(tok)
            break
        if tok in nums:
            row = nums[tok]
            break
    if row is None:
        return None
    return (col, row)


def flota_ship_at(st, pid, cell):
    for ship in st["ships"][pid]:
        if cell in ship:
            return ship
    return None


def flota_result(st, shooter, target, cell):
    ship = flota_ship_at(st, target, cell)
    if ship is None:
        return "agua", None
    tiros = st["shots"][shooter]
    if all(c in tiros or c == cell for c in ship):
        return "hundido", ship
    return "tocado", None


def flota_all_sunk(st, shooter, target):
    return all(c in st["shots"][shooter] for ship in st["ships"][target] for c in ship)


def flota_state(room):
    st = room.get("flota") or {}
    out = {"current": st["order"][st["idx"]] if st.get("order") else "", "winner": st.get("winner"),
           "boards": {}, "shots": {}}
    for pid in st.get("order", []):
        celdas = {}
        for ship in st["ships"][pid]:
            for cell in ship:
                celdas[cell] = "barco"
        rival = next((x for x in st["order"] if x != pid), None)
        if rival:
            for cell, res in st["shots"][rival].items():
                celdas[cell] = res if celdas.get(cell) != "barco" else f"barco-{res}"
        out["boards"][pid] = {f"{c}{r}": v for (c, r), v in celdas.items()}
        out["shots"][pid] = {f"{c}{r}": v for (c, r), v in st["shots"][pid].items()}
    return out


async def flota_turn(room):
    st = room["flota"]
    if st.get("winner"):
        return
    pid = st["order"][st["idx"]]
    if is_game_bot(room, pid):
        room["phase"] = "flota"
        await broadcast(room, room_state(room))
        await asyncio.sleep(scaled_bot_delay(room,2))
        await flota_app_shoot(room)
        return
    player = next(p for p in room["players"] if p["id"] == pid)
    room["phase"] = "flota"
    await narrate(room, f"{player['name']}, tu turno: decí una coordenada, como «B cuatro», o tocá el tablero rival.")
    await broadcast(room, room_state(room))
    await tell(player, {"event": "your_turn", "kind": "flota"})
    room["timer_task"] = narrated_timer(room,turn_clock(room, pid))


async def flota_finish(room, winner):
    st = room["flota"]
    st["winner"] = winner
    cancel_timer(room)
    await broadcast(room, room_state(room))
    if is_game_bot(room, winner):
        await narrate(room, "¡Hundí toda tu flota! Gané yo. ¿Revancha? Ubico los barcos de nuevo.")
        room["flota"] = new_flota(room)
        await flota_turn(room)
        return
    player = next(p for p in room["players"] if p["id"] == winner)
    await game_over(room, player)


async def flota_shoot(room, player, cell):
    st = room.get("flota")
    if not st or room["phase"] != "flota" or st.get("winner"):
        return
    if st["order"][st["idx"]] != player["id"]:
        return
    if cell in st["shots"][player["id"]]:
        await narrate(room, f"{player['name']}, ya disparaste a {flota_coord_name(cell)}. Elegí otra.", to=player)
        return
    cancel_timer(room)
    target = next(x for x in st["order"] if x != player["id"])
    result, ship = flota_result(st, player["id"], target, cell)
    st["shots"][player["id"]][cell] = result
    nombre = flota_coord_name(cell)
    if result == "agua":
        await narrate(room, f"{player['name']} dispara a {nombre}: agua.")
    elif result == "tocado":
        await narrate(room, f"{player['name']} dispara a {nombre}: ¡tocado!")
    else:
        await narrate(room, f"{player['name']} dispara a {nombre}: ¡hundido {FLOTA_NOMBRES[len(ship)]}!")
    if flota_all_sunk(st, player["id"], target):
        await flota_finish(room, player["id"])
        return
    st["idx"] = (st["idx"] + 1) % len(st["order"])
    await flota_turn(room)


def flota_app_cell(st, pid="app"):
    tiros = st["shots"][pid]
    # caza: si hay tocados sin hundir, tirar alrededor
    for ship_targets in st["target"][pid]:
        if ship_targets not in tiros:
            return ship_targets
    for (c, r), res in list(tiros.items()):
        if res in ("tocado",):
            for dc, dr in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                ci = FLOTA_LETRAS.index(c) + dc
                rr = r + dr
                if 0 <= ci < 8 and 1 <= rr <= 8 and (FLOTA_LETRAS[ci], rr) not in tiros:
                    st["target"][pid].append((FLOTA_LETRAS[ci], rr))
                    return (FLOTA_LETRAS[ci], rr)
    while True:
        cell = (random.choice(FLOTA_LETRAS), random.randint(1, 8))
        if cell not in tiros:
            return cell


async def flota_app_shoot(room):
    st = room["flota"]
    pid = st["order"][st["idx"]]
    if st.get("winner"):
        return
    cell = scaled_bot_move(room,flota_app_cell(st,pid),[(c,r) for c in FLOTA_LETRAS for r in range(1,9) if (c,r) not in st["shots"][pid]])
    target = next(x for x in st["order"] if x != pid)
    result, ship = flota_result(st, pid, target, cell)
    st["shots"][pid][cell] = result
    nombre = flota_coord_name(cell)
    if result == "agua":
        await narrate(room, f"Disparo a {nombre}: agua.")
    elif result == "tocado":
        await narrate(room, f"Disparo a {nombre}: ¡tocado!")
    else:
        await narrate(room, f"Disparo a {nombre}: ¡hundí {FLOTA_NOMBRES[len(ship)]}!")
    if flota_all_sunk(st, pid, target):
        await flota_finish(room, pid)
        return
    st["idx"] = (st["idx"] + 1) % len(st["order"])
    await flota_turn(room)



VEINTIUNO_PALOS = ["picas", "corazones", "tréboles", "diamantes"]
VEINTIUNO_RANKS = ["as", "dos", "tres", "cuatro", "cinco", "seis", "siete",
                   "ocho", "nueve", "diez", "sota", "reina", "rey"]
VEINTIUNO_ART = {"as": "el", "sota": "la", "reina": "la", "rey": "el"}


def veintiuno_new_deck():
    deck = [(r, p) for p in VEINTIUNO_PALOS for r in VEINTIUNO_RANKS]
    random.shuffle(deck)
    return deck


def veintiuno_card_name(card):
    r, p = card
    art = VEINTIUNO_ART.get(r, "el")
    return f"{art} {r} de {p}"


def veintiuno_total(cards):
    total = 0
    ases = 0
    for r, _ in cards:
        if r == "as":
            ases += 1
            total += 11
        elif r in ("sota", "reina", "rey"):
            total += 10
        else:
            total += VEINTIUNO_RANKS.index(r) + 1
    while total > 21 and ases:
        total -= 10
        ases -= 1
    return total


def new_veintiuno():
    return {"deck": veintiuno_new_deck(), "hand": None}


def veintiuno_state(room):
    st = room.get("veintiuno") or {}
    hand = st.get("hand")
    return {
        "cards": [veintiuno_card_name(c) for c in hand["cards"]] if hand else [],
        "total": veintiuno_total(hand["cards"]) if hand else None,
        "house_cards": [veintiuno_card_name(c) for c in hand.get("house", [])] if hand else [],
        "house_total": veintiuno_total(hand["house"]) if hand and hand.get("house") else None,
    }


def veintiuno_draw(room):
    st = room["veintiuno"]
    if not st["deck"]:
        st["deck"] = veintiuno_new_deck()
    return st["deck"].pop()


async def veintiuno_start_hand(room, player):
    st = room["veintiuno"]
    cards = [veintiuno_draw(room), veintiuno_draw(room)]
    st["hand"] = {"player": player["id"], "cards": cards, "house": []}
    room["phase"] = "veintiuno"
    total = veintiuno_total(cards)
    if total == 21:
        await narrate(room, f"{player['name']}, salen {veintiuno_card_name(cards[0])} y "
                            f"{veintiuno_card_name(cards[1])}: ¡veintiuno!")
        await veintiuno_resolve(room, player)
        return
    await narrate(room, f"{player['name']}, jugás esta mano contra la banca. Salen "
                        f"{veintiuno_card_name(cards[0])} y {veintiuno_card_name(cards[1])}: "
                        f"tenés {total}. ¿Carta o te plantás?")
    await broadcast(room, room_state(room))
    await tell(player, {"event": "your_turn", "kind": "veintiuno"})
    room["timer_task"] = narrated_timer(room,turn_clock(room, player["id"]))


async def veintiuno_resolve(room, player):
    st = room["veintiuno"]
    hand = st["hand"]
    room["phase"] = "veintiuno_resolve"
    total = veintiuno_total(hand["cards"])
    veintiuno_natural = total == 21 and len(hand["cards"]) == 2
    house = []
    while veintiuno_total(house) < 17:
        house.append(veintiuno_draw(room))
    house_total = veintiuno_total(house)
    hand["house"] = house
    house_cards = ", ".join(veintiuno_card_name(c) for c in house)
    await narrate(room, f"{player['name']} se planta con {total}. "
                        f"Juega la banca: {house_cards}. La banca tiene {house_total}.")
    puntos = 0
    if house_total > 21 or total > house_total:
        puntos = 2 if veintiuno_natural else 1
    if puntos:
        score = room["scores"].get(player["id"], 0) + puntos
        sync_score(room, player, score)
        if veintiuno_natural:
            await narrate(room, f"¡Veintiuno! Vale doble: {puntos} puntos para {player['name']}, que lleva {score}.")
        else:
            await narrate(room, f"Le ganás a la banca {total} a {house_total}. "
                                f"Punto para {player['name']}, que lleva {score}.")
    elif house_total == total:
        await narrate(room, f"Empate en {total}. Sin punto para nadie.")
    else:
        await narrate(room, f"Gana la banca con {house_total}. Sin punto esta vez.")
    await broadcast(room, room_state(room))
    await end_turn(room)


async def veintiuno_move(room, player, move):
    st = room.get("veintiuno")
    hand = st and st.get("hand")
    if room["phase"] != "veintiuno" or not hand or hand["player"] != player["id"]:
        return
    cancel_timer(room)
    if move == "carta":
        card = veintiuno_draw(room)
        hand["cards"].append(card)
        total = veintiuno_total(hand["cards"])
        name = veintiuno_card_name(card)
        if total > 21:
            room["phase"] = "veintiuno_resolve"
            await narrate(room, f"{name}. Te pasaste con {total}: la mano es de la banca.")
            await broadcast(room, room_state(room))
            await end_turn(room)
            return
        if total == 21:
            await narrate(room, f"{name}. ¡21! Te plantás.")
            await veintiuno_resolve(room, player)
            return
        await narrate(room, f"{name}. Tenés {total}. ¿Carta o te plantás?")
        await broadcast(room, room_state(room))
        room["timer_task"] = narrated_timer(room,turn_clock(room, player["id"]))
        return
    await veintiuno_resolve(room, player)



TRUCO_META = 15
TRUCO_PALOS = ["oros", "copas", "espadas", "bastos"]
TRUCO_RANKS = ["as", "dos", "tres", "cuatro", "cinco", "seis", "siete", "sota", "caballo", "rey"]
TRUCO_ART = {"as": "el", "sota": "la", "caballo": "el", "rey": "el"}
TRUCO_CANTOS = {2: "truco", 3: "retruco", 4: "vale cuatro"}


def truco_new_deck():
    deck = [(r, p) for p in TRUCO_PALOS for r in TRUCO_RANKS]
    random.shuffle(deck)
    return deck


def truco_card_name(card):
    r, p = card
    return f"{TRUCO_ART.get(r, 'el')} {r} de {p}"


def truco_valor(card):
    r, p = card
    if r == "as" and p == "espadas":
        return 14
    if r == "as" and p == "bastos":
        return 13
    if r == "siete" and p == "espadas":
        return 12
    if r == "siete" and p == "oros":
        return 11
    if r == "tres":
        return 10
    if r == "dos":
        return 9
    if r == "as":
        return 8
    if r == "rey":
        return 7
    if r == "caballo":
        return 6
    if r == "sota":
        return 5
    if r == "siete":
        return 4
    if r == "seis":
        return 3
    if r == "cinco":
        return 2
    return 1


def truco_envido_valor(card):
    r, _ = card
    if r in ("sota", "caballo", "rey"):
        return 0
    return TRUCO_RANKS.index(r) + 1


def truco_envido_puntos(hand):
    por_palo = {}
    for c in hand:
        por_palo.setdefault(c[1], []).append(truco_envido_valor(c))
    best = 0
    for vals in por_palo.values():
        vals = sorted(vals, reverse=True)
        if len(vals) >= 2:
            best = max(best, 20 + vals[0] + vals[1])
        else:
            best = max(best, vals[0])
    return best


def truco_tiene_flor(hand):
    return len(hand) == 3 and len(set(c[1] for c in hand)) == 1


def truco_flor_puntos(hand):
    return 20 + sum(truco_envido_valor(c) for c in hand)


def new_truco(room):
    ids = [p["id"] for p in room["players"] if not p.get("gone") and not p.get("spectator")]
    vs_app = len(ids) == 1
    order = ids + (["app"] if vs_app else [])
    return {"order": order, "vs_app": vs_app, "mano_inicial": 0, "hand": None, "winner": None}


def truco_deal(st):
    deck = truco_new_deck()
    hands = {pid: [deck.pop(), deck.pop(), deck.pop()] for pid in st["order"]}
    st["hand"] = {"hands": hands, "mano": 0, "plays": {}, "manos": [],
                  "stake": 1, "canto_de": None, "envido_done": False,
                  "flor_sung": [], "to_play": None}
    leader = st["order"][st["mano_inicial"] % 2]
    st["hand"]["to_play"] = leader
    return st["hand"]


def truco_state(room):
    st = room.get("truco") or {}
    hand = st.get("hand")
    if not hand:
        return {"hands": {}, "manos": [], "stake": 1, "current": "", "mano": 0}
    return {
        "hands": {pid: [truco_card_name(c) for c in cards] for pid, cards in hand["hands"].items()},
        "manos": hand["manos"],
        "stake": hand["stake"],
        "current": hand["to_play"],
        "mano": hand["mano"],
        "plays": {pid: truco_card_name(c) for pid, c in hand["plays"].items()},
        "flor_sung": hand["flor_sung"],
    }


def truco_actor(room, pid):
    return cartas_actor_name(room, pid)


async def truco_announce_points(room, pid, puntos, motivo):
    player = next((p for p in room["players"] if p["id"] == pid), None)
    room_st = room["truco"]
    score = room["scores"].get(pid, 0) + puntos
    if is_game_bot(room, pid) or player is None:
        room["scores"][pid] = score
        await narrate(room, f"{motivo}: {puntos} puntos para mí, llevo {score}.")
    else:
        sync_score(room, player, score)
        await narrate(room, f"{motivo}: {puntos} puntos para {player['name']}, que lleva {score}.")
    if score >= TRUCO_META:
        room_st["winner"] = pid


async def truco_prompt(room):
    st = room["truco"]
    hand = st["hand"]
    if st.get("winner"):
        return
    pid = hand["to_play"]
    room["phase"] = "truco"
    if is_game_bot(room, pid):
        await broadcast(room, room_state(room))
        await asyncio.sleep(scaled_bot_delay(room,2))
        await truco_app_play(room)
        return
    player = next(p for p in room["players"] if p["id"] == pid)
    cards = hand["hands"][pid]
    hand_txt = ", ".join(truco_card_name(c) for c in cards)
    opciones = "Jugá una carta"
    if truco_tiene_flor(cards) and pid not in hand["flor_sung"]:
        opciones = "Tenés flor: cantala"
    elif hand["mano"] == 0 and not hand["plays"] and not hand["envido_done"]:
        opciones += ", cantá envido"
    if hand["stake"] == 1:
        opciones += ", o cantá truco"
    elif hand["stake"] in (2, 3) and hand["canto_de"] != pid:
        opciones += f", o cantá {TRUCO_CANTOS[hand['stake'] + 1]}"
    await narrate(room, f"{player['name']}, tu turno (mano {hand['mano'] + 1}).")
    await narrate(room, f"Tenés: {hand_txt}. {opciones}.", to=player)
    await broadcast(room, room_state(room))
    await tell(player, {"event": "your_turn", "kind": "truco"})
    room["timer_task"] = narrated_timer(room,turn_clock(room, pid))


async def truco_sing_flor(room, player):
    st = room["truco"]
    hand = st["hand"]
    pid = player["id"]
    if hand.get("flor_done") or pid in hand["flor_sung"] or not truco_tiene_flor(hand["hands"][pid]):
        return
    cancel_timer(room)
    hand["flor_done"] = True
    hand["envido_done"] = True  # flor takes precedence over envido
    flores = [q for q in st["order"] if truco_tiene_flor(hand["hands"][q])]
    for q in flores:
        hand["flor_sung"].append(q)
        await narrate(room, f"{truco_actor(room, q)} canta: ¡flor!")
    mano = st["order"][st["mano_inicial"] % 2]
    ganador = max(flores, key=lambda q: (truco_flor_puntos(hand["hands"][q]), q == mano))
    await truco_announce_points(room, ganador, 3, "Flor")
    if st.get("winner"):
        await truco_end_match(room)
        return
    await broadcast(room, room_state(room))
    await truco_prompt(room)


async def truco_sing_envido(room, player, tipo):
    st = room["truco"]
    hand = st["hand"]
    if hand["mano"] != 0 or hand["plays"] or hand["envido_done"]:
        return
    if any(truco_tiene_flor(cards) for cards in hand["hands"].values()):
        await narrate(room, "Con flor no se juega envido: primero hay que cantar la flor.", to=player)
        return
    hand["envido_done"] = True
    puntos = 3 if tipo == "real" else 2
    hand["envido_pending"] = (puntos, player["id"])
    rival = next(x for x in st["order"] if x != player["id"])
    nombre = "real envido" if tipo == "real" else "envido"
    await narrate(room, f"{player['name']} canta: ¡{nombre}!")
    if is_game_bot(room, rival):
        await asyncio.sleep(scaled_bot_delay(room,1))
        mios = truco_envido_puntos(hand["hands"][rival])
        await truco_answer_envido(room,None,scaled_bot_move(room,mios>=25,[True,False]))
        return
    room["phase"] = "truco_envido"
    otro = next(p for p in room["players"] if p["id"] == rival)
    await narrate(room, f"{otro['name']}, {player['name']} cantó {nombre}. ¿Querés?")
    await tell(otro, {"event": "your_turn", "kind": "truco_envido"})
    await broadcast(room, room_state(room))
    room["timer_task"] = narrated_timer(room,turn_clock(room, rival))


async def truco_answer_envido(room, player, quiero):
    st = room["truco"]
    hand = st["hand"]
    pend = hand.get("envido_pending")
    if not pend:
        return
    puntos, de = pend
    hand["envido_pending"] = None
    rival = next(x for x in st["order"] if x != de)
    if not quiero:
        caidos = 1  # uncalled envido or real envido is worth one
        await narrate(room, f"{truco_actor(room, rival)} no quiere.")
        await truco_announce_points(room, de, caidos, "Envido no querido")
    else:
        await narrate(room, f"{truco_actor(room, rival)} quiere.")
        a = truco_envido_puntos(hand["hands"][de])
        b = truco_envido_puntos(hand["hands"][rival])
        await narrate(room, f"Envido: {truco_actor(room, de)} tiene {a}, {truco_actor(room, rival)} tiene {b}.")
        if a == b:
            ganador = st["order"][st["mano_inicial"] % 2]  # gana el mano
            await narrate(room, "Empate: gana el que es mano.")
        else:
            ganador = de if a > b else rival
        await truco_announce_points(room, ganador, puntos, "Gana el envido")
    if st.get("winner"):
        await truco_end_match(room)
        return
    await broadcast(room, room_state(room))
    await truco_prompt(room)


async def truco_sing_canto(room, player, nivel):
    st = room["truco"]
    hand = st["hand"]
    if nivel != hand["stake"] + 1 or nivel > 4:
        return
    if hand["stake"] > 1 and hand["canto_de"] == player["id"]:
        return  # no se puede subir el propio canto
    prev = hand["stake"]
    hand["stake_pending"] = (nivel, player["id"], prev)
    rival = next(x for x in st["order"] if x != player["id"])
    await narrate(room, f"{player['name']} canta: ¡{TRUCO_CANTOS[nivel]}!")
    if is_game_bot(room, rival):
        await asyncio.sleep(scaled_bot_delay(room,1))
        mio_max = max(truco_valor(c) for c in hand["hands"][rival])
        await truco_answer_canto(room,None,scaled_bot_move(room,mio_max>=8,[True,False]))
        return
    room["phase"] = "truco_canto"
    otro = next(p for p in room["players"] if p["id"] == rival)
    await narrate(room, f"{otro['name']}, {player['name']} cantó {TRUCO_CANTOS[nivel]}. ¿Querés?")
    await tell(otro, {"event": "your_turn", "kind": "truco_canto"})
    await broadcast(room, room_state(room))
    room["timer_task"] = narrated_timer(room,turn_clock(room, rival))


async def truco_answer_canto(room, player, quiero):
    st = room["truco"]
    hand = st["hand"]
    pend = hand.get("stake_pending")
    if not pend:
        return
    nivel, de, prev = pend
    hand["stake_pending"] = None
    rival = next(x for x in st["order"] if x != de)
    if not quiero:
        await narrate(room, f"{truco_actor(room, rival)} no quiere.")
        await truco_announce_points(room, de, prev, f"{TRUCO_CANTOS[nivel]} no querido")
        if st.get("winner"):
            await truco_end_match(room)
            return
        await truco_new_hand(room)
        return
    hand["stake"] = nivel
    hand["canto_de"] = de
    await narrate(room, f"{truco_actor(room, rival)} quiere. La mano vale {nivel}.")
    await broadcast(room, room_state(room))
    await truco_prompt(room)


async def truco_play(room, player, card):
    st = room.get("truco")
    if not st or room["phase"] != "truco" or st.get("winner"):
        return
    hand = st["hand"]
    pid = player["id"]
    if hand["to_play"] != pid or card not in hand["hands"][pid]:
        return
    if truco_tiene_flor(hand["hands"][pid]) and pid not in hand["flor_sung"]:
        await narrate(room, f"{player['name']}, tenés flor: cantala primero.", to=player)
        return
    cancel_timer(room)
    hand["hands"][pid].remove(card)
    hand["plays"][pid] = card
    await narrate(room, f"{player['name']} juega {truco_card_name(card)}.")
    rival = next(x for x in st["order"] if x != pid)
    if rival not in hand["plays"]:
        hand["to_play"] = rival
        await broadcast(room, room_state(room))
        await truco_prompt(room)
        return
    await truco_resolve_mano(room)


async def truco_resolve_mano(room):
    st = room["truco"]
    hand = st["hand"]
    a, b = st["order"]
    va, vb = truco_valor(hand["plays"][a]), truco_valor(hand["plays"][b])
    if va == vb:
        hand["manos"].append(None)
        await narrate(room, f"Mano {hand['mano'] + 1}: parda.")
    else:
        ganador = a if va > vb else b
        hand["manos"].append(ganador)
        hand["to_play"] = ganador
        await narrate(room, f"Mano {hand['mano'] + 1} para {truco_actor(room, ganador)}.")
    hand["plays"] = {}
    hand["mano"] += 1
    wins = {pid: hand["manos"].count(pid) for pid in st["order"]}
    fin = max(wins.values()) == 2 or hand["mano"] == 3
    if hand["mano"] == 2:
        primero, segundo = hand["manos"]
        if (primero is None and segundo is not None) or (primero is not None and segundo is None):
            fin = True
    if not fin:
        if hand["manos"][-1] is None:
            hand["to_play"] = st["order"][st["mano_inicial"] % 2]
        await broadcast(room, room_state(room))
        await truco_prompt(room)
        return
    if wins[a] == wins[b]:
        ganador = next((g for g in hand["manos"] if g), st["order"][st["mano_inicial"] % 2])
        await narrate(room, "Manos empatadas: gana el que ganó primero.")
    else:
        ganador = a if wins[a] > wins[b] else b
    await narrate(room, f"Mano para {truco_actor(room, ganador)}: vale {hand['stake']}.")
    await truco_announce_points(room, ganador, hand["stake"], f"Truco")
    if st.get("winner"):
        await truco_end_match(room)
        return
    await truco_new_hand(room)


async def truco_new_hand(room):
    st = room["truco"]
    st["mano_inicial"] += 1
    truco_deal(st)
    hand = st["hand"]
    for pid in st["order"]:
        if pid != "app":
            player = next(p for p in room["players"] if p["id"] == pid)
            hand_txt = ", ".join(truco_card_name(c) for c in hand["hands"][pid])
            await narrate(room, f"Nueva mano. Te tocan: {hand_txt}.", to=player)
    if truco_tiene_flor(hand["hands"].get("app", [])):
        pass  # la app la canta cuando le toque
    await narrate(room, f"Reparto de nuevo: mano {st['mano_inicial'] + 1}.")
    await broadcast(room, room_state(room))
    await truco_prompt(room)


async def truco_end_match(room):
    st = room["truco"]
    cancel_timer(room)
    await broadcast(room, room_state(room))
    if is_game_bot(room, st["winner"]):
        await narrate(room, f"Llegué a {TRUCO_META} puntos: ¡gané la partida! ¿Revancha? Reparto de nuevo.")
        room["scores"] = {p["id"]: 0 for p in room["players"] if not p.get("spectator")}
        room["truco"] = new_truco(room)
        truco_deal(room["truco"])
        await truco_prompt(room)
        return
    player = next(p for p in room["players"] if p["id"] == st["winner"])
    await game_over(room, player)


async def truco_app_play(room):
    st = room["truco"]
    hand = st["hand"]
    pid = hand["to_play"]
    cards = hand["hands"][pid]
    if truco_tiene_flor(cards) and pid not in hand["flor_sung"]:
        await truco_sing_flor(room, {"id": pid, "name": "La app"})
        return
    if hand["mano"] == 0 and not hand["plays"] and not hand["envido_done"]:
        mios = truco_envido_puntos(cards)
        if scaled_bot_move(room,mios>=30,[True,False]):
            hand["envido_done"] = True
            hand["envido_pending"] = (2, pid)
            rival = next(x for x in st["order"] if x != pid)
            await narrate(room, "¡Envido!")
            room["phase"] = "truco_envido"
            player = next(p for p in room["players"] if p["id"] == rival)
            await narrate(room, f"{player['name']}, canté envido. ¿Querés?")
            await tell(player, {"event": "your_turn", "kind": "truco_envido"})
            await broadcast(room, room_state(room))
            room["timer_task"] = narrated_timer(room,turn_clock(room, rival))
            return
    if hand["stake"]==1 and hand["mano"]<3 and scaled_bot_move(room,max(truco_valor(c) for c in cards)>=10,[True,False]):
        hand["stake_pending"] = (2, pid, 1)
        rival = next(x for x in st["order"] if x != pid)
        await narrate(room, "¡Truco!")
        room["phase"] = "truco_canto"
        player = next(p for p in room["players"] if p["id"] == rival)
        await narrate(room, f"{player['name']}, canté truco. ¿Querés?")
        await tell(player, {"event": "your_turn", "kind": "truco_canto"})
        await broadcast(room, room_state(room))
        room["timer_task"] = narrated_timer(room,turn_clock(room, rival))
        return
    rival = next(x for x in st["order"] if x != pid)
    if rival in hand["plays"]:
        rival_card = hand["plays"][rival]
        ganadoras = sorted([c for c in cards if truco_valor(c) > truco_valor(rival_card)],
                           key=truco_valor)
        card = ganadoras[0] if ganadoras else min(cards, key=truco_valor)
    else:
        card = sorted(cards, key=truco_valor)[len(cards) // 2]
    card=scaled_bot_move(room,card,cards)
    hand["hands"][pid].remove(card)
    hand["plays"][pid] = card
    await narrate(room, f"Juego {truco_card_name(card)}.")
    if rival not in hand["plays"]:
        hand["to_play"] = rival
        await broadcast(room, room_state(room))
        await truco_prompt(room)
        return
    await truco_resolve_mano(room)


TRUCO_NUM = {"as": "as", "uno": "as", "1": "as", "dos": "dos", "2": "dos", "tres": "tres", "3": "tres",
             "cuatro": "cuatro", "4": "cuatro", "cinco": "cinco", "5": "cinco", "seis": "seis", "6": "seis",
             "siete": "siete", "7": "siete", "sota": "sota", "caballo": "caballo", "rey": "rey"}


def truco_parse_card(text, hand):
    tokens = norm(text).split()
    rank = next((TRUCO_NUM[t] for t in tokens if t in TRUCO_NUM), None)
    suit = next((p for p in TRUCO_PALOS if p in tokens or p[:-1] in tokens), None)
    if rank and suit:
        card = (rank, suit)
        if card in hand:
            return card
    return None


def truco_parse_move(text):
    t = norm(text)
    tokens = t.split()
    if "flor" in tokens:
        return "flor"
    if "real" in tokens and "envido" in tokens:
        return "real envido"
    if "envido" in tokens:
        return "envido"
    if "retruco" in tokens:
        return "retruco"
    if "vale" in tokens and "cuatro" in tokens:
        return "vale cuatro"
    if "truco" in tokens:
        return "truco"
    if t.startswith("no") or "paso" in tokens:
        return "no quiero"
    if "quiero" in tokens:
        return "quiero"
    return None



CORAZONES_PALOS = ["picas", "corazones", "tréboles", "diamantes"]
CORAZONES_RANKS = ["dos", "tres", "cuatro", "cinco", "seis", "siete", "ocho",
                   "nueve", "diez", "sota", "reina", "rey", "as"]
CORAZONES_META = 50
CORAZONES_NUM = {"as": "as", "uno": "as", "1": "as", "dos": "dos", "2": "dos",
                 "tres": "tres", "3": "tres", "cuatro": "cuatro", "4": "cuatro",
                 "cinco": "cinco", "5": "cinco", "seis": "seis", "6": "seis",
                 "siete": "siete", "7": "siete", "ocho": "ocho", "8": "ocho",
                 "nueve": "nueve", "9": "nueve", "diez": "diez", "10": "diez",
                 "sota": "sota", "jota": "sota", "reina": "reina", "dama": "reina",
                 "rey": "rey"}
CORAZONES_PALO_ALIASES = {"pica": "picas", "picas": "picas",
                          "corazon": "corazones", "corazones": "corazones",
                          "trebol": "tréboles", "treboles": "tréboles",
                          "diamante": "diamantes", "diamantes": "diamantes"}


def corazones_new_deck():
    deck = [(r, p) for p in CORAZONES_PALOS for r in CORAZONES_RANKS]
    random.shuffle(deck)
    return deck


def corazones_valor(card):
    return CORAZONES_RANKS.index(card[0])


def corazones_puntos(card):
    if card[1] == "corazones":
        return 1
    if card == ("reina", "picas"):
        return 13
    return 0


def corazones_sort_key(card):
    return (CORAZONES_PALOS.index(card[1]), corazones_valor(card))


def corazones_card_name(card):
    r, p = card
    art = "la" if r in ("sota", "reina") else "el"
    return f"{art} {r} de {p}"


def new_corazones(room):
    seats = [p["id"] for p in room["players"] if not p.get("spectator") and not p.get("gone")]
    names = {p["id"]: p["name"] for p in room["players"]}
    n_app = 0
    while len(seats) < 4:
        n_app += 1
        seats.append(f"app{n_app}")
        names[f"app{n_app}"] = f"App {n_app}"
    return {"seats": seats, "names": names,
            "match": {pid: 0 for pid in seats},
            "round_num": 0, "hand": None, "winner": None}


def corazones_deal(st):
    deck = corazones_new_deck()
    hands = {}
    for i, pid in enumerate(st["seats"]):
        hands[pid] = sorted(deck[i * 13:(i + 1) * 13], key=corazones_sort_key)
    leader = next(pid for pid in st["seats"] if ("dos", "tréboles") in hands[pid])
    st["round_num"] += 1
    st["hand"] = {"hands": hands, "trick": {}, "trick_order": [], "leader": leader,
                  "to_play": leader, "hearts_broken": False,
                  "taken": {pid: [] for pid in st["seats"]}, "first": True}


def corazones_next(st, pid):
    seats = st["seats"]
    return seats[(seats.index(pid) + 1) % len(seats)]


def corazones_state(room):
    st = room.get("corazones")
    if not st:
        return None
    hand = st.get("hand")
    return {
        "round_num": st["round_num"],
        "meta": CORAZONES_META,
        "to_play": hand["to_play"] if hand else None,
        "hearts_broken": hand["hearts_broken"] if hand else False,
        "plays": [f"{st['names'][pid]}: {corazones_card_name(hand['trick'][pid])}"
                  for pid in hand["trick_order"]] if hand else [],
        "match": [f"{st['names'][pid]}: {st['match'][pid]}" for pid in st["seats"]],
        "hands": {pid: [corazones_card_name(c) for c in hand["hands"][pid]]
                  for pid in st["seats"]} if hand else {},
    }


def corazones_legal(st, pid, card):
    hand = st["hand"]
    cards = hand["hands"].get(pid, [])
    if card not in cards:
        return "No tenés esa carta."
    trick = hand["trick"]
    if hand["first"] and not trick and card != ("dos", "tréboles"):
        return "La primera baza la abre el dos de tréboles."
    if hand["first"] and trick and corazones_puntos(card):
        if any(corazones_puntos(c) == 0 and
               (c[1] == trick[hand["leader"]][1] or not any(
                   q[1] == trick[hand["leader"]][1] for q in cards)) for c in cards):
            return "En la primera baza no se descartan puntos si tenés otra carta legal."
    if trick:
        palo = trick[hand["leader"]][1]
        if card[1] != palo and any(c[1] == palo for c in cards):
            return f"Tenés que acompañar con {palo}."
    elif card[1] == "corazones" and not hand["hearts_broken"] and any(
            c[1] != "corazones" for c in cards):
        return "No podés abrir con corazones hasta que se juegue el primero."
    return None


def corazones_pick(st, pid):
    hand = st["hand"]
    cards = hand["hands"][pid]
    trick = hand["trick"]
    legal = [c for c in cards if corazones_legal(st, pid, c) is None]
    if not legal:
        return None
    if not trick:
        pool = [c for c in legal if c[1] != "corazones" and c != ("reina", "picas")]
        if not pool:
            pool = [c for c in legal if c != ("reina", "picas")] or legal
        return min(pool, key=corazones_valor)
    palo = trick[hand["leader"]][1]
    siguen = [c for c in legal if c[1] == palo]
    if siguen:
        ganadora = max((trick[q] for q in hand["trick_order"] if trick[q][1] == palo),
                       key=corazones_valor)
        debajo = [c for c in siguen if corazones_valor(c) < corazones_valor(ganadora)]
        if debajo:
            return max(debajo, key=corazones_valor)
        return min(siguen, key=corazones_valor)
    if ("reina", "picas") in legal:
        return ("reina", "picas")
    hearts = [c for c in legal if c[1] == "corazones"]
    if hearts:
        return max(hearts, key=corazones_valor)
    return max(legal, key=corazones_valor)


def corazones_parse_card(text, cards):
    tokens = norm(text).split()
    rank = next((CORAZONES_NUM[t] for t in tokens if t in CORAZONES_NUM), None)
    palo = next((CORAZONES_PALO_ALIASES[t] for t in tokens
                 if t in CORAZONES_PALO_ALIASES), None)
    if rank and palo:
        card = (rank, palo)
        if card in cards:
            return card
    return None


def corazones_hand_text(st, pid):
    hand = st["hand"]["hands"][pid]
    partes = []
    for palo in CORAZONES_PALOS:
        ranks = [c[0] for c in hand if c[1] == palo]
        if ranks:
            partes.append(f"{palo}: {', '.join(ranks)}")
    return "Tus cartas: " + "; ".join(partes) + "."


async def corazones_start_match(room):
    room["corazones"] = new_corazones(room)
    st = room["corazones"]
    corazones_deal(st)
    humanos = [p["id"] for p in room["players"]]
    bots = [st["names"][pid] for pid in st["seats"] if pid not in humanos]
    intro = (f"¡Arranca la Ronda de corazones, partida {room['match']}! Cuatro jugadores, "
             "mazo de 52. Cada corazón que juntés te suma 1 punto en contra y la reina de "
             "picas te suma 13: la idea es quedarse con la menor cantidad. Abre el que tiene "
             "el dos de tréboles y hay que seguir el palo. No se puede abrir con corazones "
             "hasta que se juegue el primero. Si alguien junta los 26 puntos de la ronda hace "
             f"luna llena: no suma nada y las demás suman 26. Cuando alguien llega a "
             f"{CORAZONES_META}, gana el que tiene menos puntos.")
    if bots:
        intro += " Completan la mesa: " + ", ".join(bots) + "."
    await narrate(room, intro)
    for p in room["players"]:
        if p["id"] in st["hand"]["hands"]:
            await narrate(room, corazones_hand_text(st, p["id"]), to=p)
    await corazones_prompt(room)


async def corazones_prompt(room):
    st = room["corazones"]
    hand = st["hand"]
    if st.get("winner"):
        return
    pid = hand["to_play"]
    room["phase"] = "corazones"
    if is_game_bot(room, pid):
        await broadcast(room, room_state(room))
        await asyncio.sleep(scaled_bot_delay(room,2))
        await corazones_app_play(room)
        return
    player = next((p for p in room["players"] if p["id"] == pid), None)
    if player is None:
        return
    await tell(player, {"event": "your_turn", "kind": "corazones"})
    await narrate(room, f"Tu turno, {player['name']}.", to=player)
    await broadcast(room, room_state(room))
    room["timer_task"] = narrated_timer(room,turn_clock(room, pid))


async def corazones_app_play(room):
    st = room["corazones"]
    pid = st["hand"]["to_play"]
    legal=[c for c in st["hand"]["hands"][pid] if corazones_legal(st,pid,c) is None]
    card = scaled_bot_move(room,corazones_pick(st,pid),legal)
    if card is not None:
        await corazones_play(room, pid, card)


async def corazones_play(room, pid, card):
    st = room.get("corazones")
    if not st or room["phase"] != "corazones" or st.get("winner"):
        return
    hand = st["hand"]
    if hand["to_play"] != pid:
        return
    motivo = corazones_legal(st, pid, card)
    if motivo:
        player = next((p for p in room["players"] if p["id"] == pid), None)
        if player:
            await narrate(room, motivo, to=player)
        return
    cancel_timer(room)
    hand["hands"][pid].remove(card)
    hand["trick"][pid] = card
    hand["trick_order"].append(pid)
    if len(hand["trick"]) == 1:
        hand["leader"] = pid
    await narrate(room, f"{st['names'][pid]} juega {corazones_card_name(card)}.")
    if card[1] == "corazones" and not hand["hearts_broken"] and len(hand["trick"]) > 1:
        hand["hearts_broken"] = True
        await narrate(room, "Se jugó el primer corazón: ya se puede abrir con corazones.")
    if len(hand["trick"]) < len(st["seats"]):
        hand["to_play"] = corazones_next(st, pid)
        await corazones_prompt(room)
        return
    palo = hand["trick"][hand["leader"]][1]
    ganador = max(hand["trick_order"],
                  key=lambda q: corazones_valor(hand["trick"][q])
                  if hand["trick"][q][1] == palo else -1)
    penas = [c for q, c in hand["trick"].items() if corazones_puntos(c)]
    hand["taken"][ganador].extend(penas)
    pts = sum(corazones_puntos(c) for c in penas)
    aviso = f"Baza para {st['names'][ganador]}"
    aviso += (f", que se lleva {pts} punto{'s' if pts != 1 else ''} en contra."
              if pts else ".")
    await narrate(room, aviso)
    hand["trick"] = {}
    hand["trick_order"] = []
    hand["first"] = False
    if all(not hand["hands"][q] for q in st["seats"]):
        await corazones_end_round(room)
        return
    hand["leader"] = ganador
    hand["to_play"] = ganador
    await corazones_prompt(room)


async def corazones_end_round(room):
    st = room["corazones"]
    hand = st["hand"]
    puntos = {pid: sum(corazones_puntos(c) for c in hand["taken"][pid])
              for pid in st["seats"]}
    for pid, pts in puntos.items():
        if pts == 26:
            await narrate(room, f"¡{st['names'][pid]} juntó las 26 penas: luna llena! "
                                "No suma nada y todas las demás suman 26.")
            puntos = {q: (0 if q == pid else 26) for q in st["seats"]}
            break
    for pid in st["seats"]:
        st["match"][pid] += puntos[pid]
    resumen = "; ".join(f"{st['names'][pid]} +{puntos[pid]} (lleva {st['match'][pid]})"
                        for pid in st["seats"])
    await narrate(room, f"Cerró la ronda {st['round_num']}: {resumen}.")
    await broadcast(room, room_state(room))
    if max(st["match"].values()) >= CORAZONES_META:
        ganador = min(st["seats"], key=lambda q: (st["match"][q], st["seats"].index(q)))
        st["winner"] = ganador
        await corazones_end_match(room)
        return
    corazones_deal(st)
    await narrate(room, f"Ronda {st['round_num']}: reparto de nuevo.")
    for p in room["players"]:
        if p["id"] in st["hand"]["hands"]:
            await narrate(room, corazones_hand_text(st, p["id"]), to=p)
    await corazones_prompt(room)


async def corazones_end_match(room):
    st = room["corazones"]
    cancel_timer(room)
    await broadcast(room, room_state(room))
    ganador = st["winner"]
    player = next((p for p in room["players"] if p["id"] == ganador and not p.get("gone")), None)
    if player is None:
        await narrate(room, f"Ganó {st['names'][ganador]} con {st['match'][ganador]} puntos "
                            f"en contra. ¿Revancha? Reparto de nuevo.")
        st["match"] = {pid: 0 for pid in st["seats"]}
        st["winner"] = None
        corazones_deal(st)
        for p in room["players"]:
            if p["id"] in st["hand"]["hands"]:
                await narrate(room, corazones_hand_text(st, p["id"]), to=p)
        await corazones_prompt(room)
        return
    await narrate(room, f"¡{player['name']} tiene la menor cantidad de puntos!")
    await game_over(room, player)



DOMINO_MAX = 9
DOMINO_NUM = {"cero": 0, "blanco": 0, "0": 0, "uno": 1, "1": 1, "dos": 2, "2": 2,
              "tres": 3, "3": 3, "cuatro": 4, "4": 4, "cinco": 5, "5": 5,
              "seis": 6, "6": 6, "siete": 7, "7": 7, "ocho": 8, "8": 8,
              "nueve": 9, "9": 9}
DOMINO_NOMBRES = ["cero", "uno", "dos", "tres", "cuatro", "cinco", "seis",
                  "siete", "ocho", "nueve"]


def domino_new_set():
    tiles = [(a, b) for a in range(DOMINO_MAX + 1) for b in range(a, DOMINO_MAX + 1)]
    random.shuffle(tiles)
    return tiles


def domino_tile_name(tile):
    return f"{DOMINO_NOMBRES[tile[0]]}-{DOMINO_NOMBRES[tile[1]]}"


def domino_pips(tiles):
    return sum(a + b for a, b in tiles)


def new_trenes(room):
    seats = [p["id"] for p in room["players"] if not p.get("spectator") and not p.get("gone")]
    names = {p["id"]: p["name"] for p in room["players"]}
    n_app = 0
    while len(seats) < 4:
        n_app += 1
        seats.append(f"app{n_app}")
        names[f"app{n_app}"] = f"App {n_app}"
    return {"seats": seats, "names": names, "match": {pid: 0 for pid in seats},
            "round_double": DOMINO_MAX, "hand": None, "winner": None}


def trenes_deal(st):
    doble = st["round_double"]
    tiles = [t for t in domino_new_set() if t != (doble, doble)]
    hands = {}
    for i, pid in enumerate(st["seats"]):
        hands[pid] = sorted(tiles[i * 10:(i + 1) * 10], key=lambda t: (-(t[0] + t[1]), t))
    st["hand"] = {"engine": doble, "hands": hands,
                  "pozo": tiles[len(st["seats"]) * 10:],
                  "trains": {pid: [] for pid in st["seats"]},
                  "open": {pid: False for pid in st["seats"]},
                  "common": [], "to_play": st["seats"][0],
                  "pending": None, "passes": 0, "extra": False}


def trenes_train_end(train, engine):
    return train[-1][1] if train else engine


def trenes_dests(st, pid, tile):
    hand = st["hand"]
    dests = []
    if hand["pending"]:
        owner, num = hand["pending"]
        if tile[0] == num or tile[1] == num:
            dests.append(owner)
        return dests
    for q in st["seats"]:
        if q != pid and not hand["open"][q]:
            continue
        end = trenes_train_end(hand["trains"][q], hand["engine"])
        if tile[0] == end or tile[1] == end:
            dests.append(q)
    end = trenes_train_end(hand["common"], hand["engine"])
    if tile[0] == end or tile[1] == end:
        dests.append("common")
    return dests


def trenes_moves(st, pid):
    hand = st["hand"]
    moves = []
    for tile in hand["hands"][pid]:
        for dest in trenes_dests(st, pid, tile):
            moves.append((tile, dest))
    return moves


def trenes_state(room):
    st = room.get("trenes")
    if not st:
        return None
    hand = st.get("hand")
    if not hand:
        return None
    trains = []
    for q in st["seats"]:
        txt = ", ".join(domino_tile_name(t) for t in hand["trains"][q]) or "vacío"
        marca = " (abierto)" if hand["open"][q] else ""
        trains.append(f"{st['names'][q]}: [{hand['engine']}] {txt}{marca}")
    com = ", ".join(domino_tile_name(t) for t in hand["common"]) or "vacío"
    trains.append(f"Tren común: [{hand['engine']}] {com}")
    return {
        "engine": hand["engine"],
        "round_double": st["round_double"],
        "to_play": hand["to_play"],
        "pozo": len(hand["pozo"]),
        "trains": trains,
        "names": st["names"],
        "pending": (f"{st['names'].get(hand['pending'][0], 'Tren común')}: {hand['pending'][1]}"
                    if hand["pending"] else None),
        "match": [f"{st['names'][pid]}: {st['match'][pid]}" for pid in st["seats"]],
        "hands": {pid: [domino_tile_name(t) for t in hand["hands"][pid]]
                  for pid in st["seats"]},
        "ends": dict({q: trenes_train_end(hand["trains"][q], hand["engine"])
                      for q in st["seats"]},
                     common=trenes_train_end(hand["common"], hand["engine"])),
        "open": {q: hand["open"][q] for q in st["seats"]},
    }


def trenes_parse(text):
    t = norm(text)
    tokens = t.replace("-", " ").split()
    nums = [DOMINO_NUM[x] for x in tokens if x in DOMINO_NUM]
    tile = tuple(nums[:2]) if len(nums) >= 2 else None
    if "robo" in tokens or "robar" in tokens or "pozo" in tokens:
        accion = "robar"
    elif "paso" in tokens:
        accion = "pasar"
    else:
        accion = None
    dest = None
    if "comun" in tokens:
        dest = "common"
    elif "mi" in tokens and "tren" in tokens:
        dest = "mio"
    elif "tren" in tokens:
        idx = tokens.index("tren")
        resto = tokens[idx + 1:]
        if resto and resto[0] == "de":
            resto = resto[1:]
        if resto:
            dest = " ".join(resto)
    return {"tile": tile, "accion": accion, "dest": dest}


async def trenes_start_match(room):
    room["trenes"] = new_trenes(room)
    st = room["trenes"]
    trenes_deal(st)
    humanos = [p["id"] for p in room["players"]]
    bots = [st["names"][pid] for pid in st["seats"] if pid not in humanos]
    intro = (f"¡Arrancan los Trenes de dominó, partida {room['match']}! Cuatro jugadores, "
             f"fichas del cero al nueve. Cada ronda sale del doble {st['round_double']}. "
             "En tu turno ponés una ficha que cierre con la punta de tu tren, del tren común "
             "o de un tren marcado como abierto. Si no podés, robás una ficha del pozo; "
             "si tampoco te sirve, tu tren queda abierto y cualquiera puede jugar ahí. "
             "Con un doble jugás de nuevo; si nadie puede taparlo, hay que cubrirlo antes "
             "de seguir. Cuando alguien se queda sin fichas termina la ronda y los demás "
             "suman los puntos de sus fichas en contra. El doble de salida va bajando ronda "
             "a ronda; al final gana quien tenga menos puntos.")
    if bots:
        intro += " Completan la mesa: " + ", ".join(bots) + "."
    await narrate(room, intro)
    for p in room["players"]:
        if p["id"] in st["hand"]["hands"]:
            await narrate(room, trenes_hand_text(st, p["id"]), to=p)
    await trenes_prompt(room)


def trenes_hand_text(st, pid):
    return "Tus fichas: " + ", ".join(domino_tile_name(t) for t in st["hand"]["hands"][pid]) + "."


async def trenes_prompt(room):
    st = room["trenes"]
    hand = st["hand"]
    if st.get("winner"):
        return
    pid = hand["to_play"]
    room["phase"] = "trenes"
    if is_game_bot(room, pid):
        await broadcast(room, room_state(room))
        await asyncio.sleep(scaled_bot_delay(room,2))
        await trenes_app_turn(room)
        return
    player = next((p for p in room["players"] if p["id"] == pid), None)
    if player is None:
        return
    moves = trenes_moves(st, pid)
    aviso = f"Tu turno, {player['name']}. "
    if hand["pending"]:
        owner, num = hand["pending"]
        aviso += f"Hay un doble {DOMINO_NOMBRES[num]} sin tapar en {st['names'].get(owner, 'el tren común')}: hay que cubrirlo. "
    if moves:
        aviso += "Elegí una ficha y un tren, o decilo por voz."
    else:
        aviso += "No tenés jugada: decí «robo»."
    await tell(player, {"event": "your_turn", "kind": "trenes"})
    await narrate(room, aviso, to=player)
    await broadcast(room, room_state(room))
    room["timer_task"] = narrated_timer(room,turn_clock(room, pid))


async def trenes_play(room, pid, tile, dest):
    st = room.get("trenes")
    if not st or room["phase"] != "trenes" or st.get("winner"):
        return
    hand = st["hand"]
    if hand["to_play"] != pid or tile not in hand["hands"][pid]:
        return
    real_dest = pid if dest == "mio" else dest
    if real_dest != "common":
        real_dest = next((q for q in st["seats"]
                          if str(q) == str(real_dest) or
                          norm(st["names"][q]) == norm(str(real_dest))), real_dest)
    if real_dest not in trenes_dests(st, pid, tile):
        player = next((p for p in room["players"] if p["id"] == pid), None)
        if player:
            await narrate(room, "Esa ficha no cierra ahí. Fijate las puntas de cada tren.",
                          to=player)
        return
    cancel_timer(room)
    hand["hands"][pid].remove(tile)
    train = hand["common"] if real_dest == "common" else hand["trains"][real_dest]
    end = trenes_train_end(train, hand["engine"])
    train.append((tile[1], tile[0]) if tile[0] != end and tile[1] == end else tile)
    nombre = "el tren común" if real_dest == "common" else f"el tren de {st['names'][real_dest]}"
    await narrate(room, f"{st['names'][pid]} pone {domino_tile_name(tile)} en {nombre}.")
    if real_dest == pid:
        hand["open"][pid] = False
    if hand["pending"] and real_dest == hand["pending"][0]:
        hand["pending"] = None
    hand["passes"] = 0
    if not hand["hands"][pid]:
        await trenes_end_round(room, pid)
        return
    if tile[0] == tile[1]:
        await narrate(room, f"¡Doble {DOMINO_NOMBRES[tile[0]]}! {st['names'][pid]} juega de nuevo.")
        hand["pending"] = (real_dest, tile[0])
        hand["extra"] = True
        if not trenes_moves(st, pid):
            await trenes_draw(room, pid, forzado=True)
            if not hand["extra"]:
                return
            if hand["to_play"] != pid:
                return
            if not trenes_moves(st, pid):
                hand["extra"] = False
                hand["open"][pid] = True
                await narrate(room, f"{st['names'][pid]} no puede tapar el doble: su tren queda abierto.")
                hand["to_play"] = trenes_next(st, pid)
        await broadcast(room, room_state(room))
        await trenes_prompt(room)
        return
    hand["extra"] = False
    if not hand["hands"][pid]:
        await trenes_end_round(room, pid)
        return
    hand["to_play"] = trenes_next(st, pid)
    await trenes_prompt(room)


def trenes_next(st, pid):
    seats = st["seats"]
    return seats[(seats.index(pid) + 1) % len(seats)]


async def trenes_draw(room, pid, forzado=False):
    st = room["trenes"]
    hand = st["hand"]
    if room["phase"] != "trenes" or hand["to_play"] != pid:
        return
    player = next((p for p in room["players"] if p["id"] == pid), None)
    if not forzado and trenes_moves(st, pid):
        if player:
            await narrate(room, "Tenés jugada: elegí una ficha antes de robar.", to=player)
        return
    if hand["pozo"]:
        tile = hand["pozo"].pop()
        hand["hands"][pid].append(tile)
        hand["hands"][pid].sort(key=lambda t: (-(t[0] + t[1]), t))
        await narrate(room, f"{st['names'][pid]} roba una ficha del pozo.")
        if trenes_dests(st, pid, tile):
            await narrate(room, f"¡Le sirvió! {st['names'][pid]} la juega.")
            if player:
                await narrate(room, f"Te tocó {domino_tile_name(tile)} y cierra: la juego por vos.",
                              to=player)
            dests = trenes_dests(st, pid, tile)
            elegido = pid if pid in dests else dests[0]
            await trenes_play(room, pid, tile, elegido)
            return
        if player:
            await narrate(room, f"Te tocó {domino_tile_name(tile)} y no cierra en ningún tren.",
                          to=player)
    else:
        await narrate(room, "El pozo quedó vacío.")
    hand["extra"] = False
    if not hand["open"][pid]:
        hand["open"][pid] = True
        await narrate(room, f"El tren de {st['names'][pid]} queda abierto.")
    hand["passes"] += 1
    if hand["passes"] >= len(st["seats"]) and not hand["pozo"]:
        await trenes_end_round(room, None)
        return
    hand["to_play"] = trenes_next(st, pid)
    await trenes_prompt(room)


async def trenes_pass(room, pid):
    st = room.get("trenes")
    if not st or room["phase"] != "trenes" or st["hand"]["to_play"] != pid:
        return
    if trenes_moves(st, pid):
        player = next((p for p in room["players"] if p["id"] == pid), None)
        if player:
            await narrate(room, "Tenés jugada: no podés pasar.", to=player)
        return
    await trenes_draw(room, pid)


async def trenes_app_turn(room):
    st = room["trenes"]
    hand = st["hand"]
    pid = hand["to_play"]
    moves = trenes_moves(st, pid)
    if moves:
        def prio(m):
            tile, dest = m
            return (0 if dest == pid else 1, -(tile[0] + tile[1]))
        tile, dest = scaled_bot_move(room,sorted(moves,key=prio)[0],moves)
        await trenes_play(room, pid, tile, dest)
        return
    await trenes_draw(room, pid)


async def trenes_end_round(room, ganador):
    st = room["trenes"]
    hand = st["hand"]
    if ganador:
        await narrate(room, f"¡{st['names'][ganador]} se quedó sin fichas y cierra la ronda!")
    else:
        await narrate(room, "Nadie puede jugar y el pozo está vacío: se cierra la ronda.")
    for pid in st["seats"]:
        st["match"][pid] += domino_pips(hand["hands"][pid])
    resumen = "; ".join(f"{st['names'][pid]} lleva {st['match'][pid]}" for pid in st["seats"])
    await narrate(room, f"Puntos de la ronda: {resumen}.")
    await broadcast(room, room_state(room))
    st["round_double"] -= 1
    if st["round_double"] < 0:
        ganador = min(st["seats"], key=lambda q: (st["match"][q], st["seats"].index(q)))
        st["winner"] = ganador
        await trenes_end_match(room)
        return
    trenes_deal(st)
    await narrate(room, f"Nueva ronda: sale del doble {st['round_double']}.")
    for p in room["players"]:
        if p["id"] in st["hand"]["hands"]:
            await narrate(room, trenes_hand_text(st, p["id"]), to=p)
    await trenes_prompt(room)


async def trenes_end_match(room):
    st = room["trenes"]
    cancel_timer(room)
    await broadcast(room, room_state(room))
    ganador = st["winner"]
    player = next((p for p in room["players"] if p["id"] == ganador and not p.get("gone")), None)
    if player is None:
        await narrate(room, f"Ganó {st['names'][ganador]} con {st['match'][ganador]} puntos "
                            f"en contra. ¿Revancha? Reparto de nuevo.")
        room["trenes"] = new_trenes(room)
        st = room["trenes"]
        trenes_deal(st)
        await trenes_prompt(room)
        return
    await narrate(room, f"¡{player['name']} es el que tiene menos puntos!")
    await game_over(room, player)



PATOS_TOTAL = 7
PATOS_META = 100
PATOS_ACC_PROPS = ["sombrerito", "banderita", "lentes de sol", "moñito", "gorrita"]


def new_patos(room):
    seats = [p["id"] for p in room["players"] if not p.get("spectator") and not p.get("gone")]
    names = {p["id"]: p["name"] for p in room["players"]}
    n_app = 0
    while len(seats) < PATOS_TOTAL:
        n_app += 1
        seats.append(f"app{n_app}")
        names[f"app{n_app}"] = f"App {n_app}"
    paises = random.sample(COUNTRY_DESTINATIONS, len(seats))
    racers = {}
    for pid, pais in zip(seats, paises):
        racers[pid] = {"country": pais, "pos": 0, "skip": False,
                       "acc": random.choice(PATOS_ACC_PROPS)}
    return {"seats": seats, "names": names, "racers": racers,
            "turn_idx": 0, "round": 1, "winner": None,
            "trivia": None, "sfx": None, "sfx_seq": 0}


def patos_current(st):
    return st["seats"][st["turn_idx"] % len(st["seats"])]


def patos_sfx(st, kind):
    st["sfx"] = kind
    st["sfx_seq"] += 1


def patos_state(room):
    st = room.get("patos")
    if not st:
        return None
    trivia = st.get("trivia")
    return {
        "round": st["round"],
        "meta": PATOS_META,
        "turn": patos_current(st),
        "racers": [{"pid": pid, "name": st["names"][pid],
                    "country": r["country"],
                    "flag": COUNTRY_FLAG_CODES.get(r["country"]),
                    "acc": r["acc"], "pos": r["pos"], "skip": r["skip"]}
                   for pid, r in st["racers"].items()],
        "trivia": trivia["statement"] if trivia else None,
        "sfx": st["sfx"],
        "sfx_seq": st["sfx_seq"],
    }


def patos_parse_move(text):
    tokens = norm(text).split()
    if any(t in tokens for t in ("dado", "dados", "tirar", "tiro", "tira")):
        return "dado"
    if any(t in tokens for t in ("trivia", "pregunta", "preguntita")):
        return "trivia"
    return None


def patos_parse_answer(text):
    tokens = norm(text).split()
    if any(t in tokens for t in ("verdadero", "cierto", "verdad")):
        return True
    if "falso" in tokens or (tokens and tokens[0] == "no"):
        return False
    return None


async def patos_start_match(room):
    room["patos"] = new_patos(room)
    st = room["patos"]
    await narrate(room, f"¡Arranca la Carrera de patos, partida {room['match']}! "
                        f"{len(st['seats'])} patitos en el agua. La ruleta de países gira...")
    for pid in st["seats"]:
        r = st["racers"][pid]
        await narrate(room, f"A {st['names'][pid]} le tocó {r['country']}: "
                            f"sale con {r['acc']} y su banderita. ¡Cuac!")
        patos_sfx(st, "cuac")
    await narrate(room, "El primero en llegar a la meta cruza nadando. En tu turno elegís "
                        "«dado» para avanzar lo que salga, o «trivia» para una preguntita de "
                        "verdadero o falso que te da un impulso grande si acertás. Ojo con "
                        "los remolinos y los troncos, y aprovechá las burbujas de turbo. "
                        "Si te tiran una piedrita, ¡agachá la cabeza!")
    await broadcast(room, room_state(room))
    await patos_prompt(room)


async def patos_prompt(room):
    st = room["patos"]
    if st.get("winner"):
        return
    pid = patos_current(st)
    if st["racers"][pid]["skip"]:
        st["racers"][pid]["skip"] = False
        await narrate(room, f"{st['names'][pid]} sigue trabado en el tronco: pierde el turno.")
        await patos_next(room)
        return
    room["phase"] = "patos"
    if is_game_bot(room, pid):
        await broadcast(room, room_state(room))
        await asyncio.sleep(scaled_bot_delay(room,2))
        await patos_app_turn(room)
        return
    player = next((p for p in room["players"] if p["id"] == pid), None)
    if player is None:
        return
    await tell(player, {"event": "your_turn", "kind": "patos"})
    await narrate(room, f"Tu turno, {player['name']}: «dado» o «trivia».", to=player)
    await broadcast(room, room_state(room))
    room["timer_task"] = narrated_timer(room,turn_clock(room, pid))


async def patos_next(room):
    st = room["patos"]
    st["turn_idx"] += 1
    if st["turn_idx"] % len(st["seats"]) == 0:
        st["round"] += 1
    await patos_prompt(room)


async def patos_advance(room, pid, n, motivo):
    st = room["patos"]
    r = st["racers"][pid]
    if n > 0:
        r["pos"] += n
        patos_sfx(st, "cuac")
        await narrate(room, f"{motivo} {st['names'][pid]} avanza {n} y queda en "
                            f"{min(r['pos'], PATOS_META)} de {PATOS_META}. ¡Cuac!")
        await patos_evento(room, pid)
    else:
        await narrate(room, f"{motivo} {st['names'][pid]} no avanza esta vez.")
    r = st["racers"][pid]
    if r["pos"] >= PATOS_META:
        await patos_end(room, pid)
        return
    await patos_next(room)


async def patos_evento(room, pid):
    st = room["patos"]
    if random.random() > 0.3:
        return
    r = st["racers"][pid]
    evento = random.choice(["remolino", "tronco", "burbujas", "piedrita"])
    nombre = st["names"][pid]
    if evento == "remolino":
        r["pos"] = max(0, r["pos"] - 5)
        patos_sfx(st, "splash")
        await narrate(room, f"¡Un remolino atrapa a {nombre}! Retrocede 5.")
    elif evento == "tronco":
        r["skip"] = True
        patos_sfx(st, "tronco")
        await narrate(room, f"¡{nombre} choca con un tronco flotando! Pierde el próximo turno.")
    elif evento == "burbujas":
        r["pos"] += 6
        patos_sfx(st, "turbo")
        await narrate(room, f"¡Burbujas de turbo para {nombre}! Impulso de 6: queda en "
                            f"{min(r['pos'], PATOS_META)}.")
    else:
        adelante = [q for q in st["seats"] if q != pid
                    and st["racers"][q]["pos"] > r["pos"]]
        if not adelante:
            await narrate(room, f"{nombre} va puntero: no hay nadie adelante para molestar.")
            return
        objetivo = min(adelante, key=lambda q: st["racers"][q]["pos"])
        st["racers"][objetivo]["pos"] = max(0, st["racers"][objetivo]["pos"] - 6)
        patos_sfx(st, "piedrita")
        await narrate(room, f"¡{nombre} le tira una piedrita a {st['names'][objetivo]}! "
                            f"Retrocede 6.")


async def patos_play(room, player, move):
    st = room.get("patos")
    if not st or room["phase"] != "patos" or st.get("winner"):
        return
    pid = player["id"] if isinstance(player, dict) else player
    if patos_current(st) != pid:
        return
    cancel_timer(room)
    if move == "trivia":
        topic = random.choice(list(VOF_BANK))
        item = random.choice(difficulty_rules.question_pool(VOF_BANK[topic],VOF_BANK[topic],participant_level(room,pid),lambda x:x["statement"]))
        st["trivia"] = {"statement": item["statement"], "vf": item["vf"], "pid": pid}
        room["phase"] = "patos_trivia"
        await narrate(room, f"Preguntita para {st['names'][pid]}: «{item['statement']}» "
                            "¿Verdadero o falso?")
        await broadcast(room, room_state(room))
        room["timer_task"] = narrated_timer(room,turn_clock(room, pid))
        return
    n = random.randint(4, 10)
    await patos_advance(room, pid, n, f"El dado marca {n}.")


async def patos_answer(room, player, resp):
    st = room.get("patos")
    if not st or room["phase"] != "patos_trivia" or not st.get("trivia"):
        return
    pid = player["id"] if isinstance(player, dict) else player
    trivia = st["trivia"]
    if trivia["pid"] != pid:
        return
    cancel_timer(room)
    st["trivia"] = None
    room["phase"] = "patos"
    if resp == trivia["vf"]:
        await patos_advance(room, pid, 12, "¡Correcto!")
    else:
        await narrate(room, await wrong_answer_feedback(room, f"Era «{'verdadero' if trivia['vf'] else 'falso'}»."))
        await patos_advance(room, pid, 0, "Incorrecto.")


async def patos_app_turn(room):
    st = room["patos"]
    pid = patos_current(st)
    if random.random() < 0.4:
        topic = random.choice(list(VOF_BANK))
        item = random.choice(difficulty_rules.question_pool(VOF_BANK[topic],VOF_BANK[topic],participant_level(room,pid),lambda x:x["statement"]))
        await narrate(room, f"Elijo trivia. «{item['statement']}»...")
        await asyncio.sleep(scaled_bot_delay(room,1))
        acierta = random.random() < difficulty_rules.skill(bot_difficulty_level(room))
        await narrate(room, "Verdadero." if (item["vf"] == acierta) else
                            ("Falso." if item["vf"] else "Verdadero."))
        await patos_advance(room, pid, 12 if acierta else 0,
                            "¡Acerté!" if acierta else "Me equivoqué.")
        return
    n = random.randint(4, 10)
    await patos_advance(room, pid, n, f"El dado marca {n}.")


async def patos_end(room, ganador):
    st = room["patos"]
    cancel_timer(room)
    st["winner"] = ganador
    patos_sfx(st, "meta")
    podio = sorted(st["seats"], key=lambda q: -st["racers"][q]["pos"])[:3]
    medallas = ["🥇", "🥈", "🥉"]
    await narrate(room, f"¡{st['names'][ganador]} cruza la meta nadando! ¡Cuac cuac cuac!")
    for i, q in enumerate(podio):
        r = st["racers"][q]
        await narrate(room, f"{medallas[i]} {st['names'][q]} ({r['country']}), "
                            f"en {min(r['pos'], PATOS_META)}.")
    await broadcast(room, room_state(room))
    player = next((p for p in room["players"] if p["id"] == ganador and not p.get("gone")), None)
    if player is None:
        await narrate(room, "Esta la gané yo con mi patito. ¿Revancha? Ya largamos de nuevo.")
        await patos_start_match(room)
        return
    await game_over(room, player)










DINOSAURIOS_DESCRIPTION=("Tierra de Dinosaurios, ficción arcade original sin marcas ni dinero. "
    "La ruleta asigna país y personaje ficticio masculino o femenino; elegí entre dos antes de tu primer ataque. "
    "Trescientas oleadas, cuota diez y cinco más cada vez. Ruleta de escenario en cada oleada: selva, volcán, desierto, pantano, cueva, isla, "
    "mar, montañas, playa, glaciar, cañón, ruinas, bosque de niebla o tormenta. Tormenta suave presente y silenciable, sin tapar pistas. "
    "Máximo tres manadas simultáneas, ataque arcade de grupo, resistencia según tipo. Corredores, cuernos, voladores por arriba y nadadores. "
    "Cuota y jefe obligatorios en cada oleada; cinco jefes en la última, todos anunciados. Rex y jefes de diseño, no un ranking científico de fuerza. "
    "Tres vidas por persona, cooperativo por turnos y cuota compartida; solo o sala hasta diez con bot si falta compañía. "
    "Cuchillo, espada, ametralladora y bomba genéricos; bomba espera dos acciones. Mejoras solo con puntos virtuales, nunca dinero real. "
    "Tiempo de decisión por turno y oleada, lectura protegida y pausa de orientación. Timeout turno pierde una vida salvo escudo; "
    "timeout oleada todos pierden vida y reintentan. Sin perder vidas regala una vida al superar, máximo veinte o diez en la final. "
    "Premios por ruleta, potencia treinta puntos y escudo quince, voces/botones/pistas espaciales, música suave, tres presentaciones, explicación y compartir. Sin sangre.")


def new_dinosaurios(room):
    seats=[p['id'] for p in room['players'] if not p.get('gone') and not p.get('spectator')][:10];names={p['id']:p['name'] for p in room['players']}
    if len(seats)==1 and room.get('capacity')!=1:seats.append('app1');names['app1']='App 1'
    st=dinosaurios_rules.new_game(seats);st.update(names=names,countries=dict(zip(seats,random.sample(COUNTRY_DESTINATIONS,len(seats)))),token=0,started=None,paused=False,result='');st['characters']={q:random.choice(RACE_DRIVERS[st['countries'][q]]) for q in st['seats']};return st


def dinosaurios_state(room):
    st=room.get('dinosaurios') if room.get('game')=='dinosaurios' else None
    if not st:return None
    elapsed=max(0,time.monotonic()-st['started']) if st['started'] is not None else 0
