async def dinosaurios_announce_wave(room):
    st=room['dinosaurios'];await narrate(room,'Pasaste a la oleada '+str(st['wave'])+'. La ruleta eligió '+st['scene']+'. Tenés que matar '+str(dinosaurios_rules.quota(st['wave']))+' y vencer '+('cinco jefes' if st['wave']==300 else 'un jefe')+'. Hay '+str(round(st['budget']))+' segundos de decisión, protegemos lectura y pausa de orientación.')


async def dinosaurios_prompt(room):
    cancel_timer(room);st=room['dinosaurios'];dinosaurios_drain(st);st['token']+=1
    for q in st['seats']:room['scores'][q]=st['players'][q]['points']
    if st['winner'] is not None:
        room['phase']='gameover';await narrate(room,('¡Superaron las trescientas oleadas! '+', '.join(st['names'][q] for q in st['winner']) if st['winner'] else 'El escuadrón se quedó sin vidas. Podés empezar de nuevo.')+'.');await broadcast(room,room_state(room));return
    if st['phase'] in ('reward','retry'):
        room['phase']='dinosaurios_'+st['phase'];await narrate(room,('Oleada superada. Premio de ruleta: '+st['reward']['kind']+'. '+('Sin perder vidas: vida extra, con el límite de la oleada. ' if st['reward']['flawless'] else '')+'Tienda con puntos virtuales, nunca dinero real. ' if st['phase']=='reward' else 'Se agotó el tiempo de la oleada. Todos pierden una vida, conservan puntos y armas y reintentan la misma cuota. ')+'El anfitrión elige continuar.');await broadcast(room,room_state(room));return
    if st['paused']:
        room['phase']='dinosaurios_pause';await broadcast(room,room_state(room));return
    room['phase']='dinosaurios_wave';pid=st['turn'];token=st['token'];await broadcast(room,room_state(room));await narrate(room,st['names'][pid]+'. '+wave_environment_text(st)+dinosaurios_rules.clues(st)+' Elegí un manada por número o dirección. Podés pedir pausa de orientación.',grid_ack={'game':'dinosaurios','token':token,'turn':pid})
    if room.get('dinosaurios') is not st or st['token']!=token or room['phase']!='dinosaurios_wave':return
    if is_game_bot(room,pid):st['started']=time.monotonic();await broadcast(room,room_state(room));room['timer_task']=narrated_timer(room,dinosaurios_bot(room,st,pid,token))
    elif st['started'] is None:room['timer_task']=narrated_timer(room,dinosaurios_audio_fallback(room,st,pid,token))


async def dinosaurios_ready(room,pid,token):
    st=room.get('dinosaurios')
    if room.get('game')!='dinosaurios' or not st or room['phase']!='dinosaurios_wave' or st['turn']!=pid or st['token']!=token or st['started'] is not None or is_game_bot(room,pid):return False
    cancel_timer(room);st['started']=time.monotonic();await broadcast(room,room_state(room));room['timer_task']=narrated_timer(room,dinosaurios_deadline(room,st,pid,token));return True


async def dinosaurios_audio_fallback(room,st,pid,token):
    try:
        await asyncio.sleep(180)
        if room.get('dinosaurios') is st:await dinosaurios_ready(room,pid,token)
    except asyncio.CancelledError:pass


async def dinosaurios_bot(room,st,pid,token):
    await asyncio.sleep(scaled_bot_delay(room))
    if room.get('dinosaurios') is st and room['phase']=='dinosaurios_wave' and st['token']==token:
        p=st['players'][pid];p['weapon']='bomba' if not p['bomb_wait'] else 'ametralladora';targets=st['targets'];target=dinosaurios_rules.bot_target(st) if random.random()<difficulty_rules.skill(bot_difficulty_level(room)) else random.choice(targets)['id'];await dinosaurios_play(room,{'id':pid},'attack',target,token)


async def dinosaurios_deadline(room,st,pid,token):
    try:
        await asyncio.sleep(min(participant_seconds(room,pid,25),st['budget']))
        if room.get('dinosaurios') is st and room['phase']=='dinosaurios_wave' and st['token']==token:
            dinosaurios_drain(st)
            if st['budget']<=.05:dinosaurios_rules.expire_wave(st);st['result']='Tiempo de oleada agotado.'
            else:dinosaurios_rules.lose_life(st,pid);dinosaurios_rules.finish_if_dead(st);dinosaurios_rules.next_turn(st,pid);st['result']=st['names'][pid]+': tiempo de turno agotado, una vida menos salvo escudo.'
            await narrate(room,st['result']);await dinosaurios_prompt(room)
    except asyncio.CancelledError:pass


async def dinosaurios_play(room,player,kind,value=None,token=None):
    st=room.get('dinosaurios');pid=player['id']
    if room.get('game')!='dinosaurios' or not st or player.get('spectator') or token is not None and st['token']!=token:return False
    if kind=='replay' and room['phase']=='gameover' and bingo_host(room)==pid:room['match']+=1;await dinosaurios_start_match(room);return True
    if kind=='continue' and st['phase'] in ('reward','retry') and bingo_host(room)==pid:
        dinosaurios_rules.continue_wave(st);st['paused']=False;await dinosaurios_announce_wave(room);await dinosaurios_prompt(room);return True
    if kind=='character':
        if room['phase']!='dinosaurios_wave' or pid not in st['seats'] or pid in st['acted_players'] or value not in RACE_DRIVERS[st['countries'][pid]]:return False
        st['characters'][pid]=value;await broadcast(room,room_state(room));return True
    if kind in ('weapon','buy'):
        try:(dinosaurios_rules.choose_weapon(st,pid,value) if kind=='weapon' else dinosaurios_rules.buy(st,pid,value))
        except ValueError:return False
        await broadcast(room,room_state(room));return True
    if kind=='resume' and room['phase']=='dinosaurios_pause' and (pid==st['turn'] or bingo_host(room)==pid):st['paused']=False;await dinosaurios_prompt(room);return True
    if room['phase']!='dinosaurios_wave' or st['turn']!=pid or st['winner'] is not None:return False
    if kind=='pause':
        dinosaurios_drain(st)
        if st['budget']<=0:dinosaurios_rules.expire_wave(st);await dinosaurios_prompt(room);return False
        cancel_timer(room);st['paused']=True;room['phase']='dinosaurios_pause';st['token']+=1;await narrate(room,'Pausa de orientación, reloj detenido. '+dinosaurios_rules.clues(st));await broadcast(room,room_state(room));return True
    if kind!='attack' or not any(t['id']==value and type(value) is int for t in st['targets']):return False
    if st['players'][pid]['weapon']=='bomba' and st['players'][pid]['bomb_wait']:return False
    elapsed=time.monotonic()-st['started'] if st['started'] is not None else 0
    dinosaurios_drain(st)
    if st['budget']<=0:dinosaurios_rules.expire_wave(st);await dinosaurios_prompt(room);return False
    if elapsed>=participant_seconds(room,pid,25):
        dinosaurios_rules.lose_life(st,pid);dinosaurios_rules.finish_if_dead(st);dinosaurios_rules.next_turn(st,pid);st['result']='Tiempo de turno agotado, una vida menos salvo escudo.';await dinosaurios_prompt(room);return False
    before={t['id'] for t in st['targets'] if t['boss']}
    try:move=dinosaurios_rules.attack(st,pid,value)
    except ValueError:return False
    st['effect']='baja' if move['cleared'] else 'resiste'
    cancel_timer(room);room['phase']='dinosaurios_result';room['scores'][pid]=st['players'][pid]['points'];st['result']=st['names'][pid]+': '+('venciste a '+move['name'] if move['boss'] and move['cleared'] else 'mataste '+str(move['count']) if move['cleared'] else 'el grupo resiste, seguí atacando')+'. Mataste '+str(st['kills'])+', quedan '+str(dinosaurios_rules.quota(st['wave'])-st['kills'])+'.'+(' Perdiste '+str(move['lost'])+' vidas.' if move['lost'] else '')
    newboss=[t['name'] for t in st['targets'] if t['boss'] and t['id'] not in before]
    if newboss:st['result']+=' Ahora te enfrentás al jefe: '+', '.join(newboss)+'. La cuota sola no alcanza.'
    await narrate(room,st['result']);await broadcast(room,room_state(room));await asyncio.sleep(.3)
    if room.get('dinosaurios') is st:await dinosaurios_prompt(room)
    return True


async def dinosaurios_voice(room,player,text):
    st=room.get('dinosaurios');pid=player['id'];cmd=norm(text)
    if room.get('game')!='dinosaurios' or not st or player.get('spectator'):return False
    if cmd in ('pistas','orientacion','posiciones'):
        await narrate(room,dinosaurios_rules.clues(st),to=player);return True
    if pid in st['seats']:
        for name in RACE_DRIVERS[st['countries'][pid]]:
            if cmd in (norm(name),'elegir '+norm(name)):return await dinosaurios_play(room,player,'character',name)
    actions={'pausa':'pause','pausa de orientacion':'pause','seguir':'resume','reanudar':'resume','continuar':'continue','siguiente oleada':'continue','revancha':'replay'}
    if cmd in actions:return await dinosaurios_play(room,player,actions[cmd])
    for item in ('potencia','escudo'):
        if cmd=='comprar '+item:return await dinosaurios_play(room,player,'buy',item)
    for w in dinosaurios_rules.WEAPONS:
        if cmd in (w,'elegir '+w,'arma '+w):return await dinosaurios_play(room,player,'weapon',w)
    ordered=sorted(st['targets'],key=lambda t:t['approach'])
    for i,t in enumerate(ordered,1):
        if cmd in ('grupo '+str(t['id']),'atacar grupo '+str(t['id']),'manada '+str(t['id']),'atacar manada '+str(t['id']),'objetivo '+str(i),'atacar '+norm(t['direction']),norm(t['direction'])):return await dinosaurios_play(room,player,'attack',t['id'],st['token'])
    return False


ZOMBI_DESCRIPTION=("Oleadas Zombi, ficción arcade original, sin dinero ni instrucciones de armas reales. "
    "Trescientas oleadas: cuota diez, luego quince, veinte y cinco más por oleada. La ruleta elige escenario en cada una. "
    "Mostramos como máximo tres grupos, que representan varios zombis cuando sube la cuota. Cada ataque es una ráfaga arcade al grupo. "
    "Elegí cuchillo, espada, ametralladora o bomba, todos genéricos. La bomba espera dos acciones para recargar. "
    "Cada tipo tiene resistencia; los grupos no atacados se acercan y al llegar pueden quitarte una vida, salvo escudo. "
    "No alcanza la cuota: hay un jefe en cada oleada y tres en la trescientos. Anunciamos jefe, cuota y resto. "
    "Tres vidas por persona. Sala cooperativa por turnos, cuota compartida; máximo diez personas, solo sin rival o sala con bot si falta compañía. "
    "Reloj de decisión por oleada y por turno, protegido durante lectura y pausa de orientación. Si vence el turno perdés una vida; "
    "si vence la oleada todos pierden una vida y se reintenta, sin regalar puntos. "
    "Superar sin perder vidas regala una vida, máximo veinte, o diez en la última oleada. Ruleta de premio y tienda entre oleadas, "
    "solo puntos virtuales: potencia cuesta treinta, escudo quince, nunca dinero real. Música y sonidos originales suaves, "
    "pistas de dirección y prioridad, tres presentaciones, sangre estilizada opcional apagada al inicio, explicación y compartir.")


