    if not st:return None
    seconds=participant_seconds(room,st['turn'],45)
    return {k:st[k] for k in ('turn','mode','theme','scores','lives','used','chain','links','resets','current','seq','result')}|{'themes':list(cadena_rules.THEMES),'bank':cadena_rules.BANK,'teams':st['teams'],'token':st['token'],'players':[{'id':p,'name':st['names'][p],'country':st['countries'][p],'flag':COUNTRY_FLAG_CODES.get(st['countries'][p]),'team':st['teams'].index(cadena_rules.team(st,p))+1,'lives':st['lives'][cadena_rules.team(st,p)[0]]} for p in st['seats']],'awaiting_audio':st['started'] is None,'remaining':max(0,seconds-(time.monotonic()-st['started'])) if st['started'] else seconds,'winners':[st['names'][p] for p in st['winner']] if st['winner'] is not None else None}


