async def end_turn(room):
    """Resolve the turn: check the winner, else pass to the next player."""
    cancel_timer(room)
    room["question"] = None
    room["spinning"] = False
    winner = next(
        (p for p in room["players"] if not p.get("gone") and room["scores"].get(p["id"], 0) >= WIN_SCORE),
        None,
    )
    if winner is not None:
        await game_over(room, winner)
        return
    room["turn"] += 1
    await begin_turn(room)


async def game_over(room, winner):
    room["phase"] = "gameover"
    if room.get("team_count"):
        winner_name = "el equipo " + TEAM_NAMES[winner["team"]]
    else:
        winner_name = winner["name"]
    others = [p["name"] for p in room["players"] if not p.get("gone") and not p.get("spectator") and p["id"] != winner["id"]
              and (not room.get("team_count") or p.get("team") != winner.get("team"))]
    beat = ""
    if len(others) == 1:
        beat = f" Le ganó a {others[0]}."
    elif others:
        beat = " Le ganó a " + ", a ".join(others[:-1]) + " y a " + others[-1] + "."
    result = (f"¡Ganó {winner_name}!" if room.get("game") in
              ("cartas", "carrera", "flota", "corazones", "trenes", "patos", "pesca", "damas", "backgammon", "poker", "chinchon", "escoba", "uno_oro", "bingo", "escalera", "rosco", "pistas", "oca", "aim", "sapo", "bolos", "hockey", "tejo", "pingpong", "tenis", "ajedrez", "torre", "caballos", "autitos", "aviones", "viborita", "comepuntos", "fantasmas", "castillo", "zombi", "grua", "tesoros","laberinto","ppt","series","escondida","piedritas","motos","western","pueblos","flipper","rompebloques","bloques","feria","amigos","soldados","topo", "cocinando","veoveo", "cadena", "stop", "simon", "mochila", "vistiendo", "muneco", "pool", "metegol", "dinosaurios") else
              f"¡Ganó {winner_name} con {room['scores'].get(winner['id'], 0)} puntos!")
    await narrate(room, f"{result}{beat} En {REMATCH_SECONDS} segundos arranca una partida nueva.")
    await broadcast(room, room_state(room))
    await asyncio.sleep(REMATCH_SECONDS)
    active = [p for p in room["players"] if not p.get("gone") and not p.get("spectator")]
    if not active:
        return
    # The starter rotates: the winner never starts twice in a row by default.
    room["starter"] = (room["starter"] + 1) % len(active)
    room["match"] += 1
    await start_match(room)


def country_wildcard_result(room, player):
    opponents = [p for p in room["players"] if not p.get("gone") and not p.get("out") and not p.get("spectator")
                 and p["id"] != player["id"]
                 and (not room.get("team_count") or p.get("team") != player.get("team"))]
    roll = random.random()
    if opponents:
        effect = "gain" if roll < .5 else "lose" if roll < .75 else "opponent"
    else:
        effect = "gain" if roll < .7 else "lose"
    recipient = player
    if effect == "opponent":
        if room.get("team_count"):
            team = random.choice(sorted({p["team"] for p in opponents}))
            opponents = [p for p in opponents if p["team"] == team]
        # Sorted by fewest lives, then next turn occurrence in the active seating cycle.
        active = [p for p in room["players"] if not p.get("gone") and not p.get("spectator")]
        cycle = []
        for offset in range(len(active) * max(1, room.get("team_count", 0))):
            probe = dict(room, turn=room["turn"] + offset)
            upcoming = current_player(probe)
            if upcoming and upcoming["id"] not in cycle:
                cycle.append(upcoming["id"])
        recipient = min(opponents, key=lambda p: (quiz_lives(room,p), cycle.index(p["id"]) if p["id"] in cycle else len(cycle)))
    before = quiz_lives(room, recipient)
    after = max(0, before - 1) if effect == "lose" else min(6, before + 1)
    room["quiz_lives"][recipient["id"]] = after
    return {"effect":effect, "recipient":recipient, "before":before, "after":after}


async def country_wildcard(room, player):
    result = country_wildcard_result(room, player)
    person = result["recipient"]
    if result["effect"] == "lose":
        text = f"{player['name']}, el comodín te quita una vida. Te quedan {result['after']}."
    elif result["after"] == result["before"]:
        text = f"El comodín le regala una vida a {person['name']}, pero ya tiene el máximo de seis. No se agrega otra."
    else:
        text = f"El comodín le regala una vida a {person['name']}. Ahora tiene {result['after']} vidas."
    await narrate(room, "¡Comodín! " + text)
    if result["after"] == 0:
        await reset_quiz_after_zero(room, player)
        return
    await narrate(room, f"{player['name']}, podés volver a girar la ruleta de categorías. El próximo giro asegura una categoría.")
    await begin_turn(room)


async def do_category_spin(room, player, chosen=None):
    """The wheel lands on a category (random unless the player picked one)."""
    cancel_timer(room)
    room["spinning"] = True
    if room["game"] == "paises":
        pool = [c for c in covered_country_categories(room.get("country")) if c not in room["country_done"]]
        if not pool:
            await country_content_missing(room, player)
            return
    else:
        progress = room.get("cat_progress", {}).get(score_owner(room, player), {})
        if room.get("game") == "vof":
            pool = [t for t in VOF_BANK if progress.get(t, 0) < quiz_rules(room)["target"]]
        else:
            pool = [c for c in CATEGORIES
                    if c == "verdad_reto" or progress.get(c, 0) < QUESTIONS_PER_LEVEL]
    weights = None
    if room["game"] == "paises":
        can_wildcard = not room.get("country_last_wildcard", False) and chosen is None
        wildcard = can_wildcard and random.random() < .1
        cat = "comodin" if wildcard else chosen if chosen in pool else random.choice(pool)
        room["country_last_wildcard"] = wildcard
        weights = [.9 / len(pool)] * len(pool) + [.1] if can_wildcard else [1 / len(pool)] * len(pool)
        wheel_keys = pool + ["comodin"] if can_wildcard else pool
        labels = [COUNTRY_CATEGORIES[c] if c != "comodin" else "Comodín" for c in wheel_keys]
        idx = wheel_keys.index(cat)
        angle = ((sum(weights[:idx]) + weights[idx] / 2) * 360 + 90) % 360
    else:
        cat = chosen or random.choice(pool)
        labels = [active_category_labels(room)[c] for c in pool]
        angle = random.randint(0,359)
    await broadcast(room, {
        "event": "spin_start", "player": player["name"],
        "angle": angle,
        "labels": labels, "colors": None, "weights": weights,
    })
    await asyncio.sleep(3.5)
    room["spinning"] = False
    if cat == "comodin":
        await country_wildcard(room, player)
        return
    if cat == "verdad_reto":
        await narrate(room, "¡Giramos la ruleta! Gira, gira... ¡paró! ¡Verdad o Reto!")
        room["phase"] = "verdad_reto_ready"
        await broadcast(room, room_state(room))
        await do_spin(room, player)
        return
    room["phase"] = "question"
    where = f", por {room['country']}" if room.get("country") else ""
    await ask_question(room, player, cat, where)


async def do_country_spin(room, player):
    """La ruleta de países: lands the country the room plays for."""
    cancel_timer(room)
    eligible = [c for c in COUNTRY_DESTINATIONS if covered_country_categories(c)]
    if not eligible:
        await country_content_missing(room, player)
        return
    room["spinning"] = True
    await broadcast(room, {
        "event": "spin_start", "player": player["name"],
        "angle": random.randint(0, 359), "labels": eligible, "colors": None,
    })
    await asyncio.sleep(3.5)
    if not eligible:
        await country_content_missing(room, player)
        return
    country = random.choice(eligible)
    room["country"] = country
    room["country_used"] = {}
    room["country_done"] = set()
    room["spinning"] = False
    await narrate(room, f"¡Gira la ruleta de países! Gira, gira... ¡paró! ¡{country}! "
                        f"En {country} hay {len(covered_country_categories(country))} categorías verificadas disponibles de {len(COUNTRY_CATEGORIES)}. "
                        "Para ganar el país hay que completar todas; si falta contenido, tu progreso se conserva sin sumar un país incompleto. "
                        f"Arranca {player['name']}.")
    # The first category follows the country automatically. No hidden second step.
    room["phase"] = "category_spinning"
    await broadcast(room, room_state(room))
    await narrate(room, f"{player['name']}, ahora giramos automáticamente la primera categoría de {country}. "
                  "No tenés que tocar otro botón. Después escuchás la pregunta y sus cuatro opciones.")
    await do_category_spin(room, player)


async def do_spin(room, player):
    """Verdad o Reto: the wheel spins, then the card is read aloud."""
    cancel_timer(room)
    room["spinning"] = True
    segment = random.choice(SEGMENTS)
    bank, used = (RETOS, room["used_retos"]) if segment == "reto" else (VERDADES, room["used_verdades"])
    available = [item for item in bank if item not in used]
    if not available:
        used.clear()
        available = list(bank)
    pick = random.choice(available)
    used.add(pick)
    angle = random.randint(0, 359)
    await broadcast(room, {
        "event": "spin_start", "player": player["name"], "angle": angle,
        "segment": segment,
        "colors": [SEGMENT_COLORS[s] for s in SEGMENTS],
        "labels": [SEGMENT_LABELS[s] for s in SEGMENTS],
    })
    label = SEGMENT_LABELS[segment]
    announce = (
        f"¡Giramos la ruleta! Gira, gira... ¡paró! ¡{player['name']}, te salió {label}! "
        f"{label} para {player['name']}: {pick}"
    )
    await asyncio.sleep(3.5)  # the wheel spins ~4s; the voice lands as it stops
    await narrate(room, announce)
    room["phase"] = "verdad_reto"
    await tell(player, {"event": "await_done", "card": pick, "label": label})
    await broadcast(room, room_state(room))


def public_question(room):
    q = room.get("question")
    if not q or room["phase"] not in ("question","escalera_question"):
        return None
    player = current_player(room)
    return {"event": "question", "id": q.get("id"), "category": q["category"],
            "q": q["q"], "options": q["options"], "player": player["id"] if player else None,
            "audio": q.get("audio"), "audio_ready": q.get("audio_ready", False),
            "clock_started": q.get("clock_started", False), "difficulty_auto": True,
            "removed": q.get("removed", []), "second_chance": bool(q.get("attempt")),
            "remaining_seconds": q.get("remaining_seconds"),
            "difficulty": difficulty_rules.name(q.get("difficulty_estimated",player_difficulty(player)))}


async def start_question_clock(room, player, question_id):
    if room.get('game')=='escalera':
        q=room.get('question');st=room['escalera']
        if room['phase']=='escalera_question' and q and q['id']==question_id and current_player(room) is player and not q['clock_started']:
            q['clock_started']=True;cancel_timer(room)
            await broadcast(room,{'event':'question_clock','id':question_id,'seconds':participant_seconds(room,player['id'],60)})
            room['timer_task']=narrated_timer(room,escalera_clock(room,player['id'],st['prompt_id']))
        return
    q = room.get("question")
    if (room["phase"] != "question" or not q or q.get("id") != question_id
            or current_player(room) is not player or q.get("clock_started")):
        return
    gate=room.get("natural_voice_gate")
    if gate is not None:gate.set()
    q["clock_started"] = True
    cancel_timer(room)
    if second_chance_enabled(room, q):
        seconds = q.get("remaining_seconds", difficulty_rules.seconds(player_difficulty(player),TURN_SECONDS))
        q["deadline"] = asyncio.get_running_loop().time() + seconds
        await broadcast(room, {"event":"question_clock", "id":question_id, "seconds":seconds})
        room["timer_task"] = narrated_timer(room,second_chance_clock(room, player, question_id, seconds))
    else:
        await broadcast(room, {"event": "question_clock", "id": question_id, "seconds": difficulty_rules.seconds(player_difficulty(player),TURN_SECONDS)})
        room["timer_task"] = narrated_timer(room,turn_clock(room, player["id"]))


async def ask_question(room, player, category, where=""):
    cancel_timer(room)
    run = room.get("quiz_run")
    if not run or run["player"] != player["id"] or run["category"] != category:
        run = new_quiz_run(room, player, category)
    try:
        question, options, correct = pick_mc(room, category)
    except ValueError:
        if room.get("game") != "paises":
            raise
        await country_content_missing(room, player)
        return
    options = list(options)
    correct_text = options[correct]
    random.shuffle(options)
    correct = options.index(correct_text)
    room["question_seq"] = room.get("question_seq", 0) + 1
    qid = room["question_seq"]
    room["question"] = {"id": qid, "category": category, "q": question, "options": options,
                        "correct": correct, "clock_started": False, "audio_ready": False,
                        "difficulty_estimated":room.get("last_question_auto_level",player_difficulty(player))}
    room["phase"] = "question"
    # Text and controls arrive before any slow voice request. No clock yet.
    await broadcast(room, public_question(room))
    await broadcast(room, room_state(room))
    if room.get("game") == "paises" and not run.get("scene_announced"):
        run["scene_announced"] = True
        await narrate(room, f"{player['name']}, " + COUNTRY_SCENES[room["country_scene"]])
    spoken = question + " " + " ".join(f"{opt}." for opt in options)
    life_count = quiz_lives(room, player)
    kind_word = "Tema" if room.get("game") == "vof" else "Categoría"
    await narrate(room, f"{kind_word} {active_category_labels(room)[category]}{where}, para {player['name']}. "
                  f"Llevás {run['correct']} de {quiz_rules(room)['target']} correctas. "
                  f"Tenés {life_count} {'vida' if life_count == 1 else 'vidas'}. {spoken}",
                  voice="es-AR-ElenaNeural" if category == "deportes" else room["question_voice"], question_id=qid)
    # The owning browser arms the clock after playback, or its explicit button.


COUNTRY_SCENES = {
    "parque": "Hoy jugamos en un parque imaginario, con brisa y pajaritos.",
    "plaza": "La mesa se mudó a una plaza imaginaria, junto a una fuente suave.",
    "playa": "Hoy jugamos en una playa imaginaria. Llegan olitas a la orilla.",
    "lluvia": "Cayeron gotitas: hoy jugamos bajo una llovizna imaginaria, sin mojarnos.",
    "tormenta": "Hoy hay lluvia imaginaria y un trueno lejano, muy suave. La taza está a salvo.",
    "sol": "Salió el sol en nuestro juego. Hay una brisa suave y la merienda espera.",
}


QUIZ_START_LIVES = 4
QUIZ_RUN_LENGTH = 5


def quiz_rules(room):
    if room.get("game") in ("paises", "vof"):
        return {"initial": 3, "target": 3, "cap": 6, "max_questions": 10 if room.get("game") == "paises" else None}
    return {"initial": QUIZ_START_LIVES, "target": QUIZ_RUN_LENGTH, "cap": 4, "max_questions": None}


def quiz_lives(room, player):
    """Lives are personal, including when category progress belongs to a team."""
    return room.setdefault("quiz_lives", {}).setdefault(player["id"], quiz_rules(room)["initial"])


def new_quiz_run(room, player, category):
    run = {"player": player["id"], "owner": score_owner(room, player),
           "category": category, "answered": 0, "correct": 0, "mistakes": 0, "streak": 0}
    room["quiz_run"] = run
    if room.get("game") == "paises":
        room["country_scene"] = random.choice(list(COUNTRY_SCENES))
    quiz_lives(room, player)
    return run


def record_quiz_answer(room, player, correct):
    """Pure bookkeeping; progression/zero-life rules remain with the caller."""
    run = room["quiz_run"]
    if run["player"] != player["id"]:
        raise ValueError("answer does not belong to the active category run")
    run["answered"] += 1
    if correct:
        run["correct"] += 1
        run["streak"] = run.get("streak", 0) + 1
    else:
        run["streak"] = 0
        run["mistakes"] += 1
        room["quiz_lives"][player["id"]] = max(0, quiz_lives(room, player) - 1)
    return run


def quiz_bonus(room, player):
    run = room["quiz_run"]
    rules = quiz_rules(room)
    qualified = (run.get("correct", 0) >= rules["target"] if room.get("game") in ("paises", "vof")
                 else run.get("streak", 0) >= rules["target"])
    if qualified and not run.get("bonus_given"):
        room["quiz_lives"][player["id"]] = min(rules["cap"], quiz_lives(room, player) + 1)
        run["bonus_given"] = True
        return True
    return False


async def reset_quiz_after_zero(room, player):
    room["quiz_lives"][player["id"]] = quiz_rules(room)["initial"]
    player.pop("out", None)
    if not room.get("team_count"):
        room.setdefault("cat_progress", {}).pop(player["id"], None)
        room["countries_won"].pop(player["id"], None)
        room["scores"][player["id"]] = 0
        room["country"] = None
        room["country_done"] = set()
    life_word = "tres" if room.get("game") in ("paises", "vof") else "cuatro"
    reset_text = (f"Tu equipo conserva sus niveles. Vos reiniciás con {life_word} vidas. "
                  if room.get("team_count") else f"Volvés al principio, nivel uno, con {life_word} vidas. ")
    await narrate(room, f"{player['name']}, te quedaste sin vidas. " + reset_text + "Girá la ruleta de nuevo.")
    await begin_turn(room)


def second_chance_enabled(room, question):
    return room.get("game") in ("categorias", "paises", "vof") and len(question.get("options", [])) == 4


async def second_chance_clock(room, player, qid, seconds):
    await asyncio.sleep(max(0, seconds))
    q = room.get("question")
    if q and q.get("id") == qid and room.get("phase") == "question" and current_player(room) is player:
        await resolve_answer(room, player, -1)


async def resolve_answer(room, player, idx):
    question = room.get("question")
    if not question or room["phase"] != "question":
        return
    # Removed options are inert, including duplicate packets or voice answers.
    if idx in question.get("removed", []) or idx < -1 or idx >= len(question["options"]):
        return
    if second_chance_enabled(room, question) and idx >= 0 and idx != question["correct"] and not question.get("attempt"):
        room["phase"] = "second_chance_reading"
        now = asyncio.get_running_loop().time()
        seconds = question.get("remaining_seconds", difficulty_rules.seconds(player_difficulty(player),TURN_SECONDS))
        if question.get("clock_started") and question.get("deadline") is not None:
            seconds = max(0, question["deadline"] - now)
        cancel_timer(room)
        question.update(attempt=1, removed=[idx], clock_started=False, audio_ready=False, audio=None, remaining_seconds=seconds)
        # New token invalidates old ready/audio/answer packets.
        room["question_seq"] = room.get("question_seq", question["id"]) + 1
        question["id"] = room["question_seq"]
        await narrate(room, f"{player['name']}, esa opción no es correcta y queda fuera. No perdés vida. Quedan tres opciones y una última chance. Conservás {max(0, int(seconds))} segundos. Tocá Empezar a responder cuando termines de leer.")
        room["phase"] = "question"
        await broadcast(room, public_question(room))
        await broadcast(room, room_state(room))
        return
    # Close this question before awaiting narration, preventing duplicate submissions.
    room["phase"] = "answering"
    cancel_timer(room)
    if not room.get("quiz_run"):
        new_quiz_run(room, player, question["category"])
    correct = idx == question["correct"]
    run = record_quiz_answer(room, player, correct)
    if correct:
        await narrate(room, f"¡Correcto, {player['name']}! Llevás {run['correct']} de {quiz_rules(room)['target']} correctas.")
    else:
        letters = ["A", "B", "C", "D"]
        right = question["options"][question["correct"]]
        picked = letters[idx] if 0 <= idx < len(letters) else "sin respuesta"
        lives = quiz_lives(room, player)
        if idx >= 0:
            prefix = await wrong_answer_feedback(room, "")
        else:
            prefix = "Se acabó el tiempo. "
        await narrate(room, prefix + f"{player['name']}, la {picked} no es la correcta. "
                      f"Es la {letters[question['correct']]}: {right}. "
                      f"Perdiste una vida, te quedan {['cero', 'una', 'dos', 'tres', 'cuatro', 'cinco', 'seis'][lives]}.")
        if lives == 0:
            await reset_quiz_after_zero(room, player)
            return
    if run["correct"] >= quiz_rules(room)["target"]:
        before_bonus = quiz_lives(room, player)
        if quiz_bonus(room, player):
            if room.get("game") in ("paises", "vof"):
                bonus_text = ("Ganaste una vida." if before_bonus < 6 else "Ya tenés el máximo de seis vidas; no se agrega otra.")
                await narrate(room, f"¡Tres correctas! {bonus_text} Tenés {quiz_lives(room, player)} vidas.")
            else:
                await narrate(room, f"¡Cinco correctas seguidas! Ganaste una vida, te regalamos una. "
                              f"Tenés {quiz_lives(room, player)}; el máximo es cuatro.")
        category = run["category"]
        level_word = "tema" if room.get("game") == "vof" else "nivel"
        await narrate(room, f"¡{player['name']} pasó el {level_word} de {active_category_labels(room)[category]}!")
        if room["game"] == "paises":
            room["country_done"].add(category)
            if len(room["country_done"]) >= len(COUNTRY_CATEGORIES):
                owner = score_owner(room, player)
                won = room["countries_won"].get(owner, 0) + 1
                room["countries_won"][owner] = won
                sync_score(room, player, won)
                country = room["country"]
                room["country"] = None
                room["country_done"] = set()
                await narrate(room, f"¡{player['name']} completó {country}!")
                if won >= COUNTRIES_TO_WIN:
                    await game_over(room, player)
                    return
            else:
                await narrate(room, f"Pasó al nivel {len(room['country_done']) + 1}. Seguís, {player['name']}.")
            await begin_turn(room)
        else:
            rules = quiz_rules(room)
            progress = room.setdefault("cat_progress", {}).setdefault(score_owner(room, player), {})
            progress[category] = rules["target"]
            passed = sum(n >= rules["target"] for n in progress.values())
            sync_score(room, player, passed)
            goal = VOF_TOPICS_TO_PASS if room.get("game") == "vof" else CATEGORIES_TO_PASS
            if passed >= goal:
                await game_over(room, player)
                return
            await end_turn(room)
        return
    await ask_question(room, player, run["category"], f", por {room['country']}" if room.get("country") else "")


async def complete_verdad_reto(room, player, done):
    if done:
        sync_score(room, player, room["scores"].get(player["id"], 0) + 1)
        await narrate(room, f"¡Muy bien, {player['name']}! Un punto. Lleva {room['scores'][player['id']]}.")
    else:
        await narrate(room, f"{player['name']} pasa. Sin punto esta vez.")
    await end_turn(room)


# ---------------------------------------------------------------------------
# El Ahorcado web: letter-by-letter word guessing, turns pass on a miss.
# ---------------------------------------------------------------------------
AHORCADO_WIN_LEVEL = 5
AH_ORDINALES = ["primer", "segundo", "tercer", "cuarto", "quinto",
                "sexto", "séptimo", "octavo", "noveno", "décimo"]


def ah_helpers():
    from rehearsal_words import (AHORCADO_BANK, AHORCADO_SPEAK, ahorcado_attempts_for,
                     ahorcado_band, ahorcado_clean, ahorcado_parse_guess)
    return AHORCADO_BANK, AHORCADO_SPEAK, ahorcado_attempts_for, ahorcado_band, ahorcado_clean, ahorcado_parse_guess


def ah_board(word, guessed):
    return " ".join(char if char in guessed else "_" for char in word)


def ah_spelled(word, speak):
    return ", ".join(speak[char] for char in word)


def ah_positions_text(word, letter, speak):
    positions=[str(i+1) for i,c in enumerate(word) if c==letter]
    return f"La letra {speak[letter]} está en " + ('el casillero ' if len(positions)==1 else 'los casilleros ') + ', '.join(positions) + '.'


def ah_formed_text(word, guessed, speak):
    import re
    visible=''.join(c if c in guessed else '_'for c in word)
    chunks=[m.group()for m in re.finditer(r'[^_]+',visible)if len(m.group())>1]
    formed=' '.join('Formaste '+chunk+': '+', '.join(speak[c]for c in chunk)+'.'for chunk in chunks)
    missing=sum(c not in guessed for c in word)
    return formed+' '+('Queda un casillero vacío.'if missing==1 else f'Quedan {missing} casilleros vacíos.')


def ah_adjacency_text(word, letter, guessed, speak):
    """'La A y la T están juntas.' for newly revealed neighbours."""
    pairs = []
    for i, char in enumerate(word):
        if char != letter:
            continue
        if i + 1 < len(word) and word[i + 1] in guessed:
            pair = (word[i], word[i + 1])
            if pair not in pairs:
                pairs.append(pair)
        if i - 1 >= 0 and word[i - 1] in guessed and word[i - 1] != letter:
            pair = (word[i - 1], word[i])
            if pair not in pairs:
                pairs.append(pair)
    return " ".join(f"La {speak[a]} y la {speak[b]} están juntas." for a, b in pairs)


async def ah_start_turn(room):
    """Deal a word at the current player's level and arm the clock."""
    _, _, attempts_for, band, _, _ = ah_helpers()
    cancel_timer(room)
    room["question"] = None
    player = current_player(room)
    if player is None:
        return
    ah = room["ahorcado"]
    room['voice_hold_until']=0
    saved = ah.setdefault("saved_words", {}).get(player["id"])
    if saved:
        ah.update({k: (set(v) if isinstance(v, set) else v) for k,v in saved.items()})
        room["phase"] = "ahorcado"
        await narrate(room, f"Vuelve {player['name']}. Conservás tu palabra y tus letras. "
                            f"Pista: {ah['hint']} Te quedan {ah['attempts']} intentos.")
        await broadcast(room, room_state(room))
        await tell(player, {"event":"your_turn", "kind":"ahorcado"})
        room["timer_task"] = narrated_timer(room,turn_clock(room,player["id"]))
        return
    level = ah["levels"].get(player["id"], 1)
    bank, _, _, _, _, _ = ah_helpers()
    lo, hi = band(level)
    choices = [(w, h) for w, h in bank if lo <= len(w) <= hi and w not in ah["used"]]
    if not choices:
        ah["used"] = {w for w in ah["used"] if not (lo <= len(w) <= hi)}
        choices = [(w, h) for w, h in bank if lo <= len(w) <= hi]
    word, hint = random.choice(difficulty_question_pool(room,[(w,h) for w,h in bank if lo<=len(w)<=hi],choices,lambda item:item[0]+" "+item[1]))
    ah["used"].add(word)
    ah.update(word=word, hint=hint, guessed=set(), wrong=set(),
              attempts=attempts_for(word))
    room["phase"] = "ahorcado"
    await narrate(room, f"Turno de {player['name']}, nivel {level}. "
                        f"Dificultad personal {difficulty_rules.name(player_difficulty(player))}, estimación automática de palabra. La palabra tiene {len(word)} letras. Pista: {hint} "
                        f"Tenés {ah['attempts']} intentos. Decí una letra o arriesgá la palabra.")
    await broadcast(room, room_state(room))
    await tell(player, {"event": "your_turn", "kind": "ahorcado"})
    room["timer_task"] = narrated_timer(room,turn_clock(room, player["id"]))


async def ah_pass(room, reason):
    """A miss: tell everyone, then the word/turn passes to the next player."""
    cancel_timer(room)
    previous = current_player(room)
    ah = room["ahorcado"]
    if previous:
        saved = ah.setdefault("saved_words", {})
        if ah["attempts"] > 0:
            saved[previous["id"]] = {k: (set(ah[k]) if isinstance(ah[k], set) else ah[k])
                for k in ("word","hint","guessed","wrong","attempts")}
        else:
            saved.pop(previous["id"], None)
    room["turn"] += 1
    nxt = current_player(room)
    await narrate(room, reason + (f" Ahora sigue {nxt['name']}." if nxt else ""))
    await ah_start_turn(room)


async def ah_guess(room, player, guess):
    ah = room["ahorcado"]
    async with ah.setdefault("guess_lock",asyncio.Lock()):
        if room["phase"] != "ahorcado" or current_player(room) is not player:
            return
        await _ah_guess_unlocked(room,player,guess)

async def _ah_guess_unlocked(room, player, guess):
    """guess = ('letter', 'E') | ('word', 'PALABRA')."""
    bank, speak, _, _, clean, _ = ah_helpers()
    ah = room["ahorcado"]
    word = ah["word"]
    kind, value = guess
    if kind == "letter":
        if value in ah["guessed"] or value in ah["wrong"]:
            await narrate(room, f"La {speak[value]} ya salió, {player['name']}. Probá otra.")
            return
        if value in word:
            ah["guessed"].add(value)
            if all(char in ah["guessed"] for char in word):
                await ah_solved(room, player)
                return
            positions = ah_positions_text(word, value, speak)
            adjacency = ah_adjacency_text(word, value, ah["guessed"], speak)
            formed=ah_formed_text(word,ah["guessed"],speak)
            spoken_board = ", ".join(speak[c] if c in ah["guessed"] else "vacío" for c in word)
            await narrate(room, f"¡Sí! {positions} {adjacency} "
                                f"{formed} Así va: {spoken_board}. "
                                f"Seguís, {player['name']}.")
            await broadcast(room, room_state(room))
            return
        await wrong_answer_feedback(room, "")
        ah["wrong"].add(value)
        ah["attempts"] -= 1
        figure = ah_miss_figure(room) if ah.get('long_campaign') else ''
        miss_beat = figure+' ' if ah.get('long_campaign') else "Perdiste, no es la correcta. "
        if ah["attempts"] <= 0:
            ending=ah_loss_line(room,word) if ah.get('long_campaign') else f"No hay {speak[value]} y se te acabaron los intentos, {player['name']}. La palabra era {ah_spelled(word, speak)}."
            await ah_pass(room,miss_beat+ending)
            return
        left = ah["attempts"]
        await ah_pass(room, miss_beat + f"No hay {speak[value]}. Te {'queda' if left == 1 else 'quedan'} "
                            f"{left} {'intento' if left == 1 else 'intentos'}, {player['name']}.")
        return
    # whole-word guess
    if value == word:
        await ah_solved(room, player)
        return
    prefix = await wrong_answer_feedback(room, "")
    ah["attempts"] -= 1
    if ah.get('long_campaign'):prefix=ah_miss_figure(room)+' '
    if ah["attempts"] <= 0:
        ending=ah_loss_line(room,word)if ah.get('long_campaign')else f"¡{ah_spelled(value, speak)} no es y se te acabaron los intentos, {player['name']}! La palabra era {ah_spelled(word,speak)}."
        await ah_pass(room,prefix+ending)
        return
    left = ah["attempts"]
    await ah_pass(room, prefix + f"{ah_spelled(value, speak)} no es. Te {'queda' if left == 1 else 'quedan'} "
                        f"{left} {'intento' if left == 1 else 'intentos'}, {player['name']}.")


async def ah_solved(room, player):
    """Solved the word: level up, tell the room where everyone stands."""
    ah = room["ahorcado"]
    ah.setdefault("saved_words", {}).pop(player["id"],None)
    level = ah["levels"].get(player["id"], 1) + 1
    ah["levels"][player["id"]] = level
    room["scores"][player["id"]] = level - 1
    others = [p for p in room["players"] if not p.get("gone") and p["id"] != player["id"]]
    standing = ""
    if others:
        otros_niveles = {ah["levels"].get(p["id"], 1) for p in others}
        if len(otros_niveles) == 1:
            standing = f"; ustedes están en el nivel {otros_niveles.pop()}"
    if level > AHORCADO_WIN_LEVEL:
        room["phase"] = "ahorcado"  # coherent until game_over
        await game_over(room, player)
        return
    await narrate(room, f"¡{player['name']} adivinó la palabra! "
                        f"{player['name']} pasó al nivel {level}{standing}.")
    room["turn"] += 1
    await ah_start_turn(room)


