def party_words(text):
    clean = ''.join(c for c in __import__("unicodedata").normalize('NFD', text.lower())
                    if __import__("unicodedata").category(c) != 'Mn')
    return __import__('re').findall(r'[a-z]+', clean)


def forbidden_words(text):
    """Whole words only: never flag 'silla', 'noche' or 'blanquear'."""
    return sorted(FORBIDDEN.intersection(party_words(text)))


def unused_pick(bank, used, rng=random, level=None):
    choices = [i for i in range(len(bank)) if i not in used]
    if not choices:
        used.clear()
        choices = list(range(len(bank)))
    if level is not None:choices=difficulty_rules.question_pool(list(range(len(bank))),choices,level,lambda i:str(bank[i]))
    idx = rng.choice(choices)
    used.add(idx)
    return idx, bank[idx]


def new_challenges():
    return {'used_ret': set(), 'used_truth': set(), 'debts': {}, 'card': None,
            'kind': None, 'remaining': 0, 'busy': False, 'deadline': None}


def finish_challenge(state, player_id, result):
    """Skip for accessibility never costs a point or adds a challenge.

    A voluntary pass adds a capped pair for the next turn. A pair cannot
    become four, eight, etc. A timeout is a pass, never a physical penalty.
    """
    if result not in ('done', 'pass', 'alternative'):
        raise ValueError('unknown challenge result')
    if result == 'alternative':
        return 'replace'
    if result == 'pass':
        state['debts'][player_id] = 2
        state['remaining'] = 0
        return 'next'
    state['remaining'] = max(0, state['remaining'] - 1)
    if state['remaining']:
        return 'another'
    state['debts'][player_id] = 1
    return 'point'


def new_syn():
    return {'used': set(), 'count': 0, 'question': None, 'pending': None,
            'history': [], 'busy': False, 'deadline': None, 'round_id': 0}


def propose_syn(state, text, source='text'):
    """Voice transcript is evidence to review, not an unquestionable verdict."""
    text = ' '.join(str(text).split())[:500]
    if not text:
        return None
    if source not in ('voice', 'text'):
        raise ValueError('unknown source')
    if state['pending'] is not None:
        return state['pending']
    pending = {'text': text, 'source': source, 'found': forbidden_words(text)}
    state['history'].append(pending.copy())
    if pending['found']:
        state['pending'] = pending
        return pending
    state['count'] += 1
    return pending


def review_syn(state, accept):
    if state['pending'] is None:
        return None
    previous = state['pending']
    state['pending'] = None
    return 'lose_turn' if accept else 'retry'

