def party_state(room):
    if room["game"] == "retos":
        st = room.get("retos", {})
        return {"kind":"retos", "card":st.get("card"), "label":st.get("kind"),
                "remaining":st.get("remaining", 0), "seconds":participant_seconds(room,current_player(room)["id"],60) if current_player(room) else 60,
                "debts":st.get("debts", {}), "goal":5}
    if room["game"] == "syn":
        st = room.get("syn", {})
        return {"kind":"syn", "question":st.get("question"), "count":st.get("count",0),
                "pending":st.get("pending"), "history":st.get("history", [])[-20:],
                "seconds":participant_seconds(room,current_player(room)["id"],30) if current_player(room) else 30, "goal":3, "round_id":st.get("round_id",0)}
    return None


async def party_idle_chatter(room, player_id, phase):
    try:
        while room["phase"] == phase:
            await asyncio.sleep(6)
            p = current_player(room)
            if not p or p["id"] != player_id or room["phase"] != phase:
                return
            await turn_chatter(room, p)
    except asyncio.CancelledError:
        pass


async def party_next_turn(room):
    cancel_timer(room)
    player = current_player(room)
    if not player:
        return
    if room["game"] == "retos":
        st = room.setdefault("retos", new_challenges())
        st["remaining"] = st["debts"].get(player["id"], 1)
        st["card"] = None
        st["busy"] = False
        room["phase"] = "retos_ready"
        await narrate(room, f"Va a jugar {player['name']}. Tocá Girar retos y verdades. "
                      + ("Tenés dos tarjetas pendientes, sin acumular más." if st["remaining"] == 2 else ""))
        await broadcast(room, room_state(room))
        room["timer_task"] = narrated_timer(room,party_idle_chatter(room,player["id"],"retos_ready"))
    else:
        room["syn"] = new_syn()
        room["phase"] = "syn_ready"
        await narrate(room, f"Va a jugar {player['name']} a Sí y no. Cuando quieras, tocá Empezar preguntas. "
                      "No digas sí, no, blanco ni negro. Podés responder por voz o por escrito.")
        await broadcast(room, room_state(room))
        room["timer_task"] = narrated_timer(room,party_idle_chatter(room,player["id"],"syn_ready"))


async def party_turn_end(room, player, point=False):
    cancel_timer(room)
    if point:
        score = room["scores"].get(player["id"], 0) + 1
        sync_score(room, player, score)
        goal = 5 if room["game"] == "retos" else 3
        await narrate(room, f"Punto para {player['name']}. Llevan {score} de {goal}.")
        if score >= goal:
            await game_over(room, player)
            return
    room["turn"] += 1
    await party_next_turn(room)


async def party_clock(room, player_id, phase, seconds):
    try:
        await wait_with_chatter(room, seconds)
        p = current_player(room)
        if not p or p["id"] != player_id or room["phase"] != phase:
            return
        if phase == "retos_card":
            await challenge_result(room, p, "pass", timeout=True)
        elif phase == "syn_question":
            room["phase"] = "syn_timeout_review"
            await narrate(room, f"Se acabó el tiempo, {p['name']}. Si estabas dictando, podés "
                          "mandar todavía la respuesta. También podés repetir la pregunta o aceptar pasar turno.")
            await broadcast(room, room_state(room))
    except asyncio.CancelledError:
        pass


async def challenge_spin(room, player, alternative=False):
    st = room["retos"]
    if st.get("busy") or current_player(room) is not player:
        return
    if room["phase"] not in ("retos_ready", "retos_card"):
        return
    cancel_timer(room)
    st["busy"] = True
    room["phase"] = "retos_spinning"
    await broadcast(room, {"event":"spin_start", "player":player["name"], "angle":random.randrange(360),
                           "labels":["RETO", "VERDAD"]})
    await asyncio.sleep(3.5)
    kind = "RETO" if random.randrange(2) == 0 else "VERDAD"
    bank = RETOS_250 if kind == "RETO" else TRUTHS
    _, text = unused_pick(bank, st["used_ret"] if kind == "RETO" else st["used_truth"])
    st.update(card=text, kind=kind, busy=False)
    room["phase"] = "retos_card"
    await broadcast(room, room_state(room))
    await narrate(room, f"{player['name']}, te salió {kind.lower()}. "
                  f"{player['name']}, tu tarjeta es: {text} "
                  "Podés elegir una alternativa accesible sin castigo. Si algo molesta, frená.")
    if current_player(room) is player and room["phase"] == "retos_card":
        await broadcast(room, {"event":"party_clock", "seconds":participant_seconds(room,player["id"],60)})
        room["timer_task"] = narrated_timer(room,party_clock(room, player["id"], "retos_card", participant_seconds(room,player["id"],60)))


async def challenge_result(room, player, result, timeout=False):
    if room["phase"] != "retos_card" or current_player(room) is not player:
        return
    st=room["retos"]
    if st.get("busy"):
        return
    if result == "alternative":
        await narrate(room, f"Otra tarjeta para {player['name']}, sin castigo. Podés hacerla sentado o con la voz.")
        await challenge_spin(room, player, alternative=True)
        return
    if result not in ("done", "pass"):
        return
    st["busy"] = True
    cancel_timer(room)
    outcome = finish_challenge(st, player["id"], result)
    if outcome == "another":
        st["busy"] = False
        room["phase"] = "retos_ready"
        await narrate(room, f"Bien, {player['name']}. Te queda una tarjeta. Girá otra vez.")
        await broadcast(room, room_state(room))
    elif outcome == "point":
        await party_turn_end(room, player, point=True)
    else:
        await narrate(room, f"{player['name']}, {'se acabó el tiempo' if timeout else 'pasaste esta tarjeta'}. "
                      "En tu próximo turno son dos tarjetas, con un máximo de dos. "
                      "Si no podés por comodidad o accesibilidad, elegí alternativa sin castigo.")
        await party_turn_end(room, player)


async def syn_question(room, player):
    cancel_timer(room)
    st = room["syn"]
    _, question = unused_pick(SYN_QUESTIONS,st["used"],level=player_difficulty(player))
    st["question"] = question
    st["round_id"] += 1
    room["phase"] = "syn_question"
    await broadcast(room, room_state(room))
    await narrate(room, f"{player['name']}, pregunta {st['count'] + 1} de cinco: {question}")
    if room["phase"] == "syn_question" and current_player(room) is player:
        await broadcast(room, {"event":"party_clock", "seconds":participant_seconds(room,player["id"],30)})
        room["timer_task"] = narrated_timer(room,party_clock(room, player["id"], "syn_question",participant_seconds(room,player["id"],30)))


async def syn_answer(room, player, text, source="text"):
    if current_player(room) is not player or room["phase"] not in ("syn_question", "syn_timeout_review", "cups_guess"):
        return
    st=room["syn"]
    if st.get("busy"):
        return
    text=' '.join(str(text).split())[:500]
    if not text:
        return
    st["busy"]=True
    cancel_timer(room)
    answer=propose_syn(st,text,source)
    await broadcast(room, {"event":"party_answer", "name":player["name"], "text":text, "source":source})
    if answer["found"]:
        room["phase"]="syn_review"
        st["busy"]=False
        await narrate(room, f"{player['name']}, recibí: {text}. Detecté: {', '.join(answer['found'])}. "
                      "Si la transcripción se equivocó, corregila o repetí sin castigo. Si es lo que dijiste, aceptá el fallo.")
        await broadcast(room,room_state(room))
        room["timer_task"]=narrated_timer(room,party_idle_chatter(room,player["id"],"syn_review"))
    elif st["count"]>=5:
        st["busy"]=False
        await narrate(room,f"¡Cinco respuestas válidas, {player['name']}!")
        await party_turn_end(room,player,point=True)
    else:
        st["busy"]=False
        await narrate(room,f"Vale, {player['name']}. Llevás {st['count']} de cinco.")
        await syn_question(room,player)


async def syn_review(room, player, decision):
    if current_player(room) is not player or room["phase"] not in ("syn_review", "syn_timeout_review"):
        return
    cancel_timer(room)
    if decision=="accept":
        review_syn(room["syn"],True)
        await narrate(room,f"Turno cerrado para {player['name']}. Seguimos sin eliminar a nadie.")
        await party_turn_end(room,player)
    elif decision=="retry":
        review_syn(room["syn"],False)
        room["phase"]="syn_question"
        await narrate(room,f"Sin castigo, {player['name']}. Podés corregir escribiendo o volver a hablar. "
                      f"La misma pregunta: {room['syn']['question']}")
        await broadcast(room,room_state(room))
        await broadcast(room,{"event":"party_clock","seconds":participant_seconds(room,player["id"],30)})
        room["timer_task"]=narrated_timer(room,party_clock(room,player["id"],"syn_question",participant_seconds(room,player["id"],30)))


