TURN_OWNED_GAMES = {"cartas", "carrera", "flota", "truco", "corazones", "trenes", "patos", "pesca", "damas", "backgammon", "poker", "chinchon", "escoba", "uno_oro", "bingo", "escalera", "rosco", "pistas", "oca", "aim", "sapo", "bolos", "hockey", "tejo", "pingpong", "tenis", "ajedrez", "torre", "caballos", "autitos", "aviones", "viborita", "comepuntos", "fantasmas", "castillo", "zombi", "grua", "tesoros","laberinto","ppt","series","escondida","piedritas","motos","western","pueblos","flipper","rompebloques","bloques","feria","amigos","soldados","topo", "cocinando","veoveo", "cadena", "stop", "simon", "mochila", "vistiendo", "muneco", "pool", "metegol", "dinosaurios", "viborita", "comepuntos", "fantasmas", "castillo", "zombi", "grua", "tesoros","laberinto","ppt","series","escondida","piedritas","motos","western","pueblos","flipper","rompebloques","bloques","feria","amigos","soldados","topo", "cocinando","veoveo", "cadena", "stop", "simon", "mochila", "vistiendo", "muneco", "pool", "metegol", "dinosaurios"}


async def retire_game_seat(room, code, player):
    was_current = current_player(room) is player
    pid = player["id"]
    player["gone"] = True
    pending = room.get("disconnect_tasks", {}).pop(pid, None)
    if pending and pending is not asyncio.current_task():
        pending.cancel()
    remaining = [p for p in room["players"] if not p.get("gone") and not p.get("spectator")]
    if not remaining:
        cancel_timer(room)
        if room.get("game")=="castillo":castillo_stop_global(room)
        room["phase"] = "gameover"
        if not any(not p.get("gone") for p in room["players"]):
            rooms.pop(code, None)
        else:
            await broadcast(room, room_state(room))
        return
    st = room[room["game"]]
    room.setdefault("bot_seats", []).append(pid)
    label = f"App (relevo de {player['name']})"
    room.setdefault("bot_names", {})[pid] = label
    if "names" in st:
        st["names"][pid] = label
    await narrate(room, f"{player['name']} salió. La app toma su lugar y conserva la partida.")
    if not was_current:
        await broadcast(room, room_state(room))
        return
    cancel_timer(room)
    phase = room["phase"]
    game = room["game"]
    if game == "cartas" and phase == "cartas_color":
        hand = st["hands"][pid]
        color = max(CARTAS_COLORS, key=lambda c: sum(t[0] == c for t in hand))
        await cartas_choose_color(room, {"id": pid, "name": label}, color)
    elif game == "truco" and phase == "truco_canto":
        hand = st["hand"]["hands"][pid]
        await truco_answer_canto(room, None, scaled_bot_move(room,max(map(truco_valor, hand), default=0)>=8,[True,False]))
    elif game == "truco" and phase == "truco_envido":
        await truco_answer_envido(room, None, scaled_bot_move(room,truco_envido_puntos(st["hand"]["hands"][pid])>=25,[True,False]))
    elif game == "pesca" and phase in ("pesca_wait", "pesca_listen", "pesca_ya"):
        st["cast_id"] += 1  # invalidate a cast that was still waiting
        st["bite_id"] = st["pique_ts"] = None
        room["phase"] = "pesca"
        await pesca_app_turn(room)
    elif game=='grua' and phase=='grua_setup':
        await broadcast(room,room_state(room))
    elif game=='tesoros' and phase=='tesoros_setup':
        await broadcast(room,room_state(room))
    elif game=='laberinto' and phase=='laberinto_setup':
        await broadcast(room,room_state(room))
    elif game=='ppt' and phase=='ppt_setup':
        await broadcast(room,room_state(room))
    elif game=='series':
        if phase!='series_setup':await series_prompt(room)
        else:await broadcast(room,room_state(room))
    elif game=='escondida':
        if phase=='escondida_hide':
            remaining=max(0,20-(time.monotonic()-st['started'])) if st['started'] is not None else 20
            token=st['token']
            async def remaining_count():
                await asyncio.sleep(remaining);await escondida_count_now(room,st,token)
            room['timer_task']=narrated_timer(room,remaining_count())
        elif phase=='escondida_search':room['timer_task']=narrated_timer(room,escondida_timer(room,st,st['token']))
        await broadcast(room,room_state(room))
    elif game=='soldados':
        if phase=='soldados':await soldados_prompt(room)
