  #castillo{width:100%;max-width:700px;}#castle-map{display:block;width:100%;max-width:550px;margin:14px auto;background:#172334;border:2px solid #a9a5b8;border-radius:14px;box-sizing:border-box;}#castle-actions,#castle-options{display:flex;flex-wrap:wrap;gap:8px;}#castle-actions button,#castle-options button{flex:1 1 150px;min-width:0;margin:0;}#castle-roulette{border:2px dashed #a8b9c9;padding:12px;border-radius:16px;}#castle-players{padding-left:22px;text-align:left;}#castle-players li{margin:9px 0;}#castle-sounds{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;text-align:left;font-size:1.05rem;min-width:0;}#castle-sounds label{min-height:42px;display:flex;align-items:center;gap:8px;}#castle-sounds input{width:22px;height:22px;}select[id^=castle-variant]{max-width:100%;font-size:1.2rem;min-height:48px;}
  #fantasmas{width:100%;max-width:650px;}#haunt-map{display:block;width:100%;max-width:480px;margin:14px auto;background:#172a38;border:2px solid #a6a4b4;border-radius:18px;box-sizing:border-box;}#haunt-doors,#haunt-options{display:flex;flex-wrap:wrap;gap:8px;}#haunt-doors button,#haunt-options button{flex:1 1 150px;min-width:0;margin:0;}#haunt-roulette{border:2px dashed #a8b9c9;padding:12px;border-radius:16px;}#haunt-roulette.spinning{animation:haunt-glow .65s ease-in-out;}@keyframes haunt-glow{50%{background:#384d60;transform:scale(.98);}}@media(prefers-reduced-motion:reduce){#haunt-roulette.spinning{animation:none;}}
