  #race-track[data-mode=autitos] .race-road{background-color:#52616b;}#race-track[data-mode=aviones] .race-road{background-color:#8bb4c8;}
  #race{max-width:700px;width:100%;}#race-track{width:100%;}.race-lane{margin:10px 0;padding:8px;background:#725945;border-radius:10px;text-align:left;}.race-lane p{margin:0 0 5px;font-size:16px;}.race-road{height:58px;position:relative;background:#a38350;border-top:2px dashed #ead2a3;border-bottom:2px dashed #ead2a3;}.race-road:after{content:'META';position:absolute;right:2px;top:2px;font-size:9px;background:#202d34;color:white;padding:2px;}.race-road svg{position:absolute;width:55px;height:52px;transition:left .6s ease;}.race-lane .flag{font-size:20px;}#race-track[data-weather=lluvia] .race-road,#race-track[data-weather=tormenta] .race-road{background:repeating-linear-gradient(120deg,#7e7765,#7e7765 15px,#b9c3c7 16px,#7e7765 18px);}
  #torre{width:100%;max-width:650px;}#tower-board{display:flex;flex-direction:column-reverse;max-width:430px;width:100%;margin:14px auto;gap:3px;}#tower-board .tower-row{display:grid;grid-template-columns:32px repeat(3,minmax(0,1fr));gap:3px;align-items:center;}#tower-board button{box-sizing:border-box;min-width:0;width:100%;margin:0!important;padding:7px 2px;border-radius:4px;font-size:13px;background:repeating-linear-gradient(8deg,#b58c5b,#b58c5b 5px,#a97e50 6px,#b58c5b 8px);color:#171d23;border:2px solid #f1d49e;}#tower-board button:disabled{opacity:.5;}#tower-board .gap{min-height:36px;border:1px dashed #766a56;border-radius:4px;}#tower-board.collapsed{gap:10px;}#tower-board.collapsed .tower-row:nth-child(odd){transform:rotate(2deg) translateX(2px);}#tower-board.collapsed .tower-row:nth-child(even){transform:rotate(-2deg) translateX(-2px);}
  #ajedrez{max-width:650px;width:100%;}#chess-board{display:grid;grid-template-columns:repeat(8,minmax(0,1fr));width:100%;max-width:420px;margin:12px auto;}#chess-board button{box-sizing:border-box;min-width:0;width:100%;padding:0;margin:0;border-radius:0;aspect-ratio:1;position:relative;font-size:10px;}#chess-board svg{width:78%;height:78%;display:block;margin:auto;}#chess-board .coord{position:absolute;left:2px;bottom:0;font-size:10px;}#chess-board .selected{outline:3px solid #f9bf45;outline-offset:-3px;}#ajedrez label{display:block;margin:10px 0 5px;}#chess-promotion{font-size:18px;padding:10px;margin-bottom:10px;}#chess-moves{display:block;width:100%;max-width:100%;font-size:18px;padding:12px;}
  #temporizador { font-size: 1.3rem; color: #ffab91; min-height: 1.8rem; }
  #jugadores { font-size: 1.1rem; color: #b2dfdb; margin: 0.5rem; list-style: none; padding: 0; }
