@router.get("/amor-con-aroma-a-cafe/flags/{code}.svg")
async def country_flag(code: str):
    svg = COUNTRY_FLAG_SVGS.get(code)
    if svg is None:
        return Response(status_code=404)
    return Response(svg, media_type="image/svg+xml", headers={"Cache-Control":"public, max-age=86400", "X-Content-Type-Options":"nosniff"})


@router.get("/amor-con-aroma-a-cafe/flags-license.txt")
async def country_flags_license():
    return Response(FLAG_ICONS_LICENSE, media_type="text/plain")


@router.get("/amor-con-aroma-a-cafe/audio/{name}")
async def serve_audio(name: str):
    """Serves a cached narration mp3 (one hour TTL)."""
    key = name[:-4] if name.endswith(".mp3") else name
    item = audio_cache.get(key)
    if item is None:
        return Response(status_code=404)
    return Response(content=item[0], media_type="audio/mpeg")


